write_file({"content":"// ============================================================
// 世界生成冒烟测试（Node 直接运行：node test/worldgen.test.js）
// 覆盖 docs/CONTRACT.md 的 ST-A 自测项：
//   3×3 区块生成 / 无 NaN / 基岩层 / 海平面有水 / 森林区有原木 /
//   getBlock-setBlock 往返一致 / 洞穴与荧石不越界
// ============================================================
'use strict';
var path = require('path');
var W = require(path.join(__dirname, '..', 'js', 'world.js'));
var B = require(path.join(__dirname, '..', 'js', 'blocks.js'));

var World = W.World, CHUNK = W.CHUNK, HEIGHT = W.HEIGHT, SEA = W.SEA;
var MC_BLOCKS = B.MC_BLOCKS;

var failures = 0;
function ok(cond, msg) {
  if (cond) { console.log('  ✓ ' + msg); }
  else { failures++; console.error('  ✗ ' + msg); }
}

console.log('== worldgen.test.js ==');
console.log('CHUNK=' + CHUNK + ' HEIGHT=' + HEIGHT + ' SEA=' + SEA);

var world = new W.World(1337);
ok(world.renderDistance === 6, '默认渲染半径 RD=6');

// ---- 1. 生成 3×3 区块 ----
for (var cx = -1; cx <= 1; cx++) {
  for (var cz = -1; cz <= 1; cz++) world.ensureData(cx, cz);
}
var chunkCount = 0;
world.chunks.forEach(function () { chunkCount++; });
ok(chunkCount === 9, '3×3 区块已生成（实际 ' + chunkCount + '）');

// ---- 2. 全域扫描：无 NaN/越界 id，统计特征 ----
var counts = {};
var badId = 0, nanLike = 0;
for (cx = -1; cx <= 1; cx++) {
  for (cz = -1; cz <= 1; cz++) {
    var c = world.getChunk(cx, cz);
    for (var i = 0; i < c.blocks.length; i++) {
      var v = c.blocks[i];
      if (v !== (v | 0) || v !== (v & 0xff) || Number.isNaN(v)) nanLike++;
      if (v >= MC_BLOCKS.length) badId++;
      counts[v] = (counts[v] || 0) + 1;
    }
  }
}
ok(nanLike === 0, '无 NaN / 非法数值');
ok(badId === 0, '无越界方块 id');
ok((counts[0] || 0) > 0, '存在空气（洞穴/树冠上方）');
ok((counts[6] || 0) > 0, '存在基岩');

// ---- 3. 基岩层：y=0 满铺，y=1 部分基岩 ----
var bedrockY0 = 0, bedrockY1 = 0, total = 0;
for (var x = 0; x < CHUNK; x++) {
  for (var z = 0; z < CHUNK; z++) {
    total++;
    if (world.getBlock(x, 0, z) === 6) bedrockY0++;
    if (world.getBlock(x, 1, z) === 6) bedrockY1++;
  }
}
ok(bedrockY0 === total, 'y=0 全部为基岩（' + bedrockY0 + '/' + total + '）');
ok(bedrockY1 > 0 && bedrockY1 < total, 'y=1 部分基岩（30% 左右，实际 ' + bedrockY1 + '/' + total + '）');

// ---- 4. y=60(SEA) 存在水 ----
var waterAtSea = 0;
for (x = -16; x < 16; x++) for (z = -16; z < 16; z++) {
  if (world.getBlock(x, SEA, z) === 11) waterAtSea++;
}
ok(waterAtSea > 0, 'y=' + SEA + ' 存在水（' + waterAtSea + ' 格）');

// 水面以下的柱：从水面向下直到实心，之间应全是水（不悬空）
var waterColumnOK = true;
for (x = -8; x < 8 && waterColumnOK; x++) for (z = -8; z < 8; z++) {
  var topWater = -1;
  for (var y = SEA; y >= 0; y--) {
    var id = world.getBlock(x, y, z);
    if (id === 11) topWater = y;
    else if (topWater >= 0 && id === 0) { waterColumnOK = false; break; }
    else if (id !== 11 && id !== 0) break;
  }
}
ok(waterColumnOK, '水体连续无悬空（洪水检查）');

// ---- 5. 找一片森林，确认有原木与树叶 ----
// 用 biomeAt 在更大范围找森林群系，再生成对应区块
var forestFound = false, logFound = false, leafFound = false;
outer:
for (var rr = 0; rr <= 20 && !forestFound; rr++) {
  for (var dx = -rr; dx <= rr; dx++) {
    for (var dz = -rr; dz <= rr; dz++) {
      if (Math.max(Math.abs(dx), Math.abs(dz)) !== rr) continue;
      if (world.biomeAt(dx * 16 + 8, dz * 16 + 8) === 1) { // 1=森林
        forestFound = true;
        for (var fx = dx * 16; fx < dx * 16 + 16; fx++) {
          for (var fz = dz * 16; fz < dz * 16 + 16; fz++) {
            world.ensureData(fx >> 4, fz >> 4);
          }
        }
        break outer;
      }
    }
  }
}
ok(forestFound, '找到森林群系区块');
if (forestFound) {
  // 在已生成区块里扫原木/树叶（跨区块树冠也计入）
  world.chunks.forEach(function (c) {
    for (var i = 0; i < c.blocks.length; i++) {
      if (c.blocks[i] === 9 || c.blocks[i] === 26) logFound = true;
      if (c.blocks[i] === 10) leafFound = true;
    }
  });
  ok(logFound, '森林区存在原木');
  ok(leafFound, '森林区存在树叶');
}

// ---- 6. getBlock / setBlock 往返一致 + 邻块标脏 ----
var rtOK = true;
for (var k = 0; k < 300; k++) {
  var bx = (k * 37) % 40 - 4, by = k % HEIGHT, bz = (k * 53) % 40 - 4;
  var id = k % MC_BLOCKS.length;
  world.setBlock(bx, by, bz, id);
  if (world.getBlock(bx, by, bz) !== id) { rtOK = false; break; }
}
ok(rtOK, 'getBlock/setBlock 往返一致（300 次随机写读）');
var c00 = world.getChunk(0, 0);
world.setBlock(0, 50, 0, 20);      // 本块
ok(c00.dirty === true, 'setBlock 后本区块标脏');
world.setBlock(0, 50, 15, 20);     // z=15 边界 → 应同时标脏 (0,1)
ok(world.getChunk(0, 1).dirty === true, '边界写读触发邻区块标脏');
// 越界安全
world.setBlock(5, -1, 5, 1); world.setBlock(5, HEIGHT, 5, 1);
ok(world.getBlock(5, -1, 5) === 0 && world.getBlock(5, HEIGHT, 5) === 0, 'y 越界读写安全');
// 未生成区块读为空气
ok(world.getBlock(9999, 50, -9999) === 0, '未生成区块 getBlock 返回 0');

// ---- 7. 出生点合法 ----
var sp = world.spawnPoint();
ok(Number.isFinite(sp.x) && Number.isFinite(sp.y) && Number.isFinite(sp.z), 'spawnPoint 有限数值');
ok(sp.y > SEA && sp.y < HEIGHT, '出生点在地表之上（y=' + sp.y + '）');

// ---- 8. 洞穴限制检查：水下柱不开洞（防洪水）----
// 抽查若干水下柱，统计水下方是否突然出现空气腔贴着水
var floodOK = true;
for (x = -8; x < 8 && floodOK; x++) for (z = -8; z < 8; z++) {
  for (y = SEA; y > 0; y--) {
    var a = world.getBlock(x, y, z), b2 = world.getBlock(x, y - 1, z);
    if (a === 11 && b2 === 0) { floodOK = false; } // 水正下方直接是空气 → 会漏水
  }
}
ok(floodOK, '水下无直接悬空空气腔（洞穴不挖穿水底）');

// ---- 9. pendingStats 结构 ----
world.setPlayerPos(8, 8);
var st = world.pendingStats();
ok(typeof st.genQueue === 'number' && typeof st.meshQueue === 'number', 'pendingStats 可用');

console.log(failures === 0 ? '\n全部通过 ✓' : '\n失败 ' + failures + ' 项 ✗');
process.exit(failures === 0 ? 0 : 1);
