  // ---------- 地形轮廓 ----------
  // 基础高度 34..64 + 细节；湖盆噪声压出湖海；山地区域 ridged 抬升到 ~90
  World.prototype.terrainHeight = function (wx, wz) {
    var s = this.seed;
    var base = fbm2(wx * 0.008, wz * 0.008, s + 11, 4, 0.5);        // 大尺度起伏
    var detail = fbm2(wx * 0.06, wz * 0.06, s + 12, 2, 0.5);        // 小尺度粗糙
    var h = 34 + base * 30 + (detail - 0.5) * 6;                    // ≈34..64
    // 湖盆：中频噪声低于阈值时把地表压到海平面以下（保证任何种子都有水域）
    var lake = fbm2(wx * 0.01, wz * 0.01, s + 16, 2, 0.5);
    if (lake < 0.38) {
      h = Math.min(h, 32 + lake * 21); // lake≈0.38 → 39.98（渐进岸线），越低越深
    }
    // 山地掩码 + ridged 抬升
    var mask = smoothstep(0.55, 0.78, fbm2(wx * 0.0028, wz * 0.0028, s + 14, 2, 0.5));
    if (mask > 0) {
      var ridge = ridged2(wx * 0.006, wz * 0.006, s + 13);
      h += mask * (26 + ridge * 42);                                // 最高 ~90+
    }
    return Math.min(92, Math.max(4, h));
  };

