write_file({"content":"// ============================================================
// HUD / 热栏 / 方块选择器 / 暂停菜单 / 调试 / 加载屏 / 水下滤镜
// DOM 骨架与样式由 index.html（ST-B）提供，本文件按 id 取用元素：
//   #game-canvas #crosshair #hotbar #block-picker #pause-menu
//   #debug #underwater-overlay #loading #title-bar
// 图标绘制：用 MC_ATLAS 的 T 表定位瓦片，从图集 canvas 采样到小 canvas。
// ============================================================
(function () {
  'use strict';

  // 图集 canvas 上的瓦片源坐标（atlas.js：索引 i → 列 i%16、行 (i/16)|0，像素左上原点）
  function tileSrc(name) {
    var atlas = window.MC_ATLAS;
    if (!atlas || !atlas.T || atlas.T[name] === undefined) return null;
    var i = atlas.T[name];
    return { col: i % 16, row: (i / 16) | 0 };
  }

  function UI() {
    this.hotbar = document.getElementById('hotbar');
    this.picker = document.getElementById('block-picker');
    this.pause = document.getElementById('pause-menu');
    this.debug = document.getElementById('debug');
    this.underwater = document.getElementById('underwater-overlay');
    this.loading = document.getElementById('loading');
    this.crosshair = document.getElementById('crosshair');
    this.titleBar = document.getElementById('title-bar');

    this.slotIds = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    this.selected = 0;
    this.pickerOpen = false;
    this.pauseOpen = false;
    this._toastTimer = null;

    // 暂停菜单按钮（index.html 提供按钮，这里绑事件；按钮缺失则忽略）
    if (this.pause) {
      var btns = this.pause.querySelectorAll('button');
      var self = this;
      for (var i = 0; i < btns.length; i++) {
        (function (b) {
          var t = (b.textContent || '').trim();
          if (t.indexOf('继续') >= 0) b.addEventListener('click', function () { self.togglePause(false); });
          // 「操作说明」按钮的展开行为由 main 注入（需要显示键位表）
        })(btns[i]);
      }
    }
  }

  // ---------------- 加载屏 ----------------
  // pct: 0..100 数字显示进度条；传 'done' 隐藏加载屏
  UI.prototype.setLoading = function (pct) {
    if (!this.loading) return;
    if (pct === 'done') {
      this.loading.style.display = 'none';
      if (this.crosshair) this.crosshair.style.display = 'block';
      if (this.titleBar) this.titleBar.style.display = 'block';
      return;
    }
    this.loading.style.display = 'flex';
    if (this.crosshair) this.crosshair.style.display = 'none';
    var bar = this.loading.querySelector('.bar-fill');
    var txt = this.loading.querySelector('.pct');
    var p = Math.max(0, Math.min(100, pct | 0));
    if (bar) bar.style.width = p + '%';
    if (txt) txt.textContent = p + '%';
  };

  // ---------------- 方块图标（热栏/选择器共用）----------------
  // isometric 简化：顶面亮/侧面暗的伪 2.5D；cross 方块直接画十字贴图。
  UI.prototype._drawBlockIcon = function (canvas, id, size) {
    var ctx = canvas.getContext('2d');
    canvas.width = size; canvas.height = size;
    ctx.imageSmoothingEnabled = false;
    ctx.clearRect(0, 0, size, size);

    var atlas = window.MC_ATLAS;
    var blocks = window.MC_BLOCKS;
    var def = blocks && blocks[id];
    if (!atlas || !atlas.texture || !def) return;

    var srcCanvas = atlas.texture.image; // CanvasTexture 的源 canvas
    if (!srcCanvas) return;

    function drawTile(tileName, dx, dy, dw, dh, darken) {
      var s = tileSrc(tileName);
      if (!s) return;
      ctx.save();
      if (darken) { ctx.globalAlpha = 1; ctx.filter = 'brightness(0.66)'; }
      ctx.drawImage(srcCanvas, s.col * 16, s.row * 16, 16, 16, dx, dy, dw, dh);
      ctx.restore();
    }

    if (def.cross) {
      drawTile(def.tex[2], size * 0.08, size * 0.08, size * 0.84, size * 0.84, false);
      return;
    }
    // 伪等距：上梯形用 top 贴图近似（直接方形+明暗分层，足够像素风）
    var top = def.tex[0], side = def.tex[2];
    drawTile(top, size * 0.12, size * 0.06, size * 0.76, size * 0.46, false);   // 顶
    drawTile(side, size * 0.12, size * 0.52, size * 0.76, size * 0.42, true);   // 侧(暗)
  };

  // ---------------- 热栏 ----------------
  UI.prototype.setHotbar = function (slotIds) {
    if (!slotIds) return;
    for (var i = 0; i < 9; i++) this.slotIds[i] = slotIds[i] | 0;
    this._renderHotbar();
  };
  UI.prototype.setSlot = function (i, id) {
    if (i < 0 || i > 8) return;
    this.slotIds[i] = id | 0;
    this._renderHotbar();
  };
  UI.prototype.selectSlot = function (i) {
    this.selected = Math.max(0, Math.min(8, i));
    this._renderHotbar();
  };
  UI.prototype._renderHotbar = function () {
    if (!this.hotbar) return;
    var self = this;
    // 仅首次重建 DOM，之后只更新（避免滚轮切换时重排闪烁）
    if (this.hotbar.children.length !== 9) {
      this.hotbar.innerHTML = '';
      for (var i = 0; i < 9; i++) {
        var cell = document.createElement('div');
        cell.className = 'slot';
        cell.dataset.index = i;
        cell.appendChild(document.createElement('canvas'));
        cell.addEventListener('click', (function (idx) {
          return function () { self.selectSlot(idx); };
        })(i));
        this.hotbar.appendChild(cell);
      }
    }
    for (var j = 0; j < 9; j++) {
      var el = this.hotbar.children[j];
      var on = j === this.selected;
      el.className = 'slot' + (on ? ' active' : '');
      var cv = el.querySelector('canvas');
      var id = this.slotIds[j];
      if (id) this._drawBlockIcon(cv, id, 40);
      else {
        var c2 = cv.getContext('2d');
        cv.width = 40; cv.height = 40;
        c2.clearRect(0, 0, 40, 40);
      }
    }
  };

  // ---------------- 方块选择器 ----------------
  UI.prototype.togglePicker = function (open) {
    if (!this.picker) return;
    this.pickerOpen = (open === undefined) ? !this.pickerOpen : !!open;
    if (this.pickerOpen) this._buildPicker();
    this.picker.style.display = this.pickerOpen ? 'flex' : 'none';
  };
  UI.prototype._buildPicker = function () {
    var self = this;
    this.picker.innerHTML = '';
    var title = document.createElement('div');
    title.className = 'picker-title';
    title.textContent = '选择方块';
    this.picker.appendChild(title);

    var grid = document.createElement('div');
    grid.className = 'picker-grid';
    var blocks = window.MC_BLOCKS;
    for (var id = 1; id < blocks.length; id++) {
      var def = blocks[id];
      if (!def || id === 6 || id === 11) continue; // 排除基岩/水
      (function (bid) {
        var item = document.createElement('div');
        item.className = 'picker-item';
        item.title = def.name;
        var cv = document.createElement('canvas');
        self._drawBlockIcon(cv, bid, 36);
        item.appendChild(cv);
        var label = document.createElement('div');
        label.className = 'picker-name';
        label.textContent = def.name;
        item.appendChild(label);
        item.addEventListener('click', function () {
          self.setSlot(self.selected, bid);
          self.togglePicker(false);
          if (self.onPick) self.onPick(bid); // main 用来同步 player.selectedBlock
        });
        grid.appendChild(item);
      })(id);
    }
    this.picker.appendChild(grid);
  };

  // ---------------- 暂停菜单 ----------------
  UI.prototype.togglePause = function (open) {
    if (!this.pause) return;
    this.pauseOpen = (open === undefined) ? !this.pauseOpen : !!open;
    this.pause.style.display = this.pauseOpen ? 'flex' : 'none';
  };
  // 「操作说明」：把键位表写进暂停菜单的说明区（main 初始化时调用一次）
  UI.prototype.setHelpText = function (html) {
    if (!this.pause) return;
    var box = this.pause.querySelector('.help-text');
    if (box) box.innerHTML = html;
  };

  // ---------------- 调试 (F3) ----------------
  UI.prototype.setDebug = function (text) {
    if (!this.debug) return;
    if (text === null || text === undefined) {
      this.debug.style.display = 'none';
    } else {
      this.debug.style.display = 'block';
      // textPre 支持多行
      this.debug.innerHTML = '';
      var lines = String(text).split('\n');
      for (var i = 0; i < lines.length; i++) {
        var div = document.createElement('div');
        div.textContent = lines[i];
        this.debug.appendChild(div);
      }
    }
  };

  // ---------------- 水下滤镜 ----------------
  UI.prototype.setUnderwater = function (b) {
    if (!this.underwater) return;
    this.underwater.style.display = b ? 'block' : 'none';
  };

  // ---------------- Toast 提示 ----------------
  UI.prototype.toast = function (msg) {
    var t = document.getElementById('toast');
    if (!t) {
      t = document.createElement('div');
      t.id = 'toast';
      document.body.appendChild(t);
    }
    t.textContent = msg;
    t.style.display = 'block';
    if (this._toastTimer) clearTimeout(this._toastTimer);
    var self = this;
    this._toastTimer = setTimeout(function () { t.style.display = 'none'; }, 1800);
  };

  window.MC_UI = { UI: UI };
})();
","path":"js/ui.js"})

write_file({"content":"// ============================================================
// 启动引导 + 主循环（浏览器端）
// 依赖加载顺序：three.js → atlas.js → blocks.js → shaders.js →
//               mesher.js → render.js → world.js → player.js → ui.js → main.js
// 职责：
//   1. 校验全局对象 → MC_RENDER.init(atlas)
//   2. seed = URL ?seed= 或 1337 → new World
//   3. Player/UI 装配、输入 hooks 桥接
//   4. 预热：同步生成出生点周围 3×3 区块（加载条）再进游戏
//   5. 主循环：物理 → 世界流式更新 → 昼夜/雾/水下 → 渲染
//   6. 视野外区块卸载（> RD+2）
// ============================================================
(function () {
  'use strict';

  var CHUNK = 16, HEIGHT = 96, SEA = 40;

  // ---------- 天空色（与 render.js 的昼夜插值约定保持一致）----------
  var SKY_NIGHT = 0x0a0e1c, SKY_DUSK = 0xd78f5a, SKY_DAY = 0x87ceeb;
  function lerp(a, b, t) { return a + (b - a) * t; }
  function lerpColor(c1, c2, t) {
    var r = lerp((c1 >> 16) & 255, (c2 >> 16) & 255, t);
    var g = lerp((c1 >> 8) & 255, (c2 >> 8) & 255, t);
    var b = lerp(c1 & 255, c2 & 255, t);
    return (Math.round(r) << 16) | (Math.round(g) << 8) | Math.round(b);
  }
  function skyColor(dayFactor) {
    if (dayFactor < 0.30) return lerpColor(SKY_NIGHT, SKY_DUSK, dayFactor / 0.30);
    if (dayFactor < 0.55) return lerpColor(SKY_DUSK, SKY_DAY, (dayFactor - 0.30) / 0.25);
    return SKY_DAY;
  }

  function boot() {
    // ---------- 0. 依赖校验 ----------
    var missing = [];
    if (!window.THREE) missing.push('three.js (CDN)');
    if (!window.MC_ATLAS) missing.push('js/atlas.js');
    if (!window.MC_BLOCKS) missing.push('js/blocks.js');
    if (!window.MC_SHADERS) missing.push('js/shaders.js');
    if (!window.MC_MESHER) missing.push('js/mesher.js');
    if (!window.MC_RENDER) missing.push('js/render.js');
    if (!window.MC_WORLD) missing.push('js/world.js');
    if (!window.MC_PLAYER) missing.push('js/player.js');
    if (!window.MC_UI) missing.push('js/ui.js');
    if (missing.length) {
      document.body.innerHTML = '<div style="color:#fff;font:16px monospace;padding:2em">' +
        '启动失败，缺少：' + missing.join('、') + '</div>';
      return;
    }

    // ---------- 1. 渲染器 ----------
    MC_RENDER.init(MC_ATLAS.texture);

    // ---------- 2. 世界与玩家 ----------
    var seed = 1337;
    try {
      var q = new URLSearchParams(window.location.search).get('seed');
      if (q !== null && q !== '' && isFinite(parseInt(q, 10))) seed = parseInt(q, 10) | 0;
    } catch (e) { /* file:// 下解析失败则用默认种子 */ }

    var world = new MC_WORLD.World(seed);
    world.renderDistance = 6;
    var ui = new MC_UI.UI();
    var player = new MC_PLAYER.Player(world, MC_RENDER.camera);
    var spawn = world.spawnPoint();
    player.spawn = spawn;
    player.teleport(spawn);

    // ---------- 3. 热栏与选块 ----------
    var hotbarIds = [2, 3, 4, 5, 9, 10, 12, 22, 20]; // 草/土/圆石/板/原木/叶/玻璃/荧石/砖
    ui.setHotbar(hotbarIds);
    ui.selectSlot(0);
    player.selectedBlock = hotbarIds[0];

    function syncSelected() {
      player.selectedBlock = ui.slotIds[ui.selected] || 0;
    }

    // ---------- 4. 输入 hooks（player → main → ui）----------
    var lastPauseEvt = 0; // ESC keydown 与 pointerlockchange 可能连发 → 去抖
    player.bindInput(document.getElementById('game-canvas'), {
      onPauseRequest: function () {
        var now = performance.now();
        if (now - lastPauseEvt < 150) return;
        lastPauseEvt = now;
        if (ui.pickerOpen) { ui.togglePicker(false); player.requestLock(); return; }
        var open = !ui.pauseOpen;
        ui.togglePause(open);
        if (open) player.releaseLock();
        else player.requestLock();
      },
      onTogglePicker: function () {
        if (ui.pauseOpen) return;
        var open = !ui.pickerOpen;
        ui.togglePicker(open);
        if (open) player.releaseLock();
        else player.requestLock();
      },
      onToggleDebug: function () {
        debugOn = !debugOn;
        ui.setDebug(debugOn ? '' : null);
      },
      onHotbarSelect: function (i) {
        ui.selectSlot(i);
        syncSelected();
      },
      onSlotScroll: function (dir) {
        ui.selectSlot((ui.selected + dir + 9) % 9);
        syncSelected();
      },
      onPickBlock: function (id) {
        // 中键：把指向方块放进当前热栏格
        ui.setSlot(ui.selected, id);
        syncSelected();
        var def = window.MC_BLOCKS[id];
        if (def) ui.toast('已选取：' + def.name);
      }
    });
    ui.onPick = syncSelected; // 选择器点击后同步 player.selectedBlock
    ui.setHelpText(
      'WASD 移动 · 空格 跳跃/上升 · Shift 潜行/下降 · Ctrl 或双击W 疾跑<br>' +
      '左键 破坏 · 右键 放置 · 中键 选取方块 · 滚轮/1-9 切换热栏<br>' +
      'E 方块选择器 · F 或双击空格 飞行 · F3 调试 · ESC 暂停'
    );

    // 暂停菜单「继续」按钮：UI 内部只 togglePause，这里补指针重锁
    if (ui.pause) {
      var resumeBtn = ui.pause.querySelector('button');
      var btns = ui.pause.querySelectorAll('button');
      for (var bi = 0; bi < btns.length; bi++) {
        if ((btns[bi].textContent || '').indexOf('继续') >= 0) {
          (function (b) {
            b.addEventListener('click', function () { player.requestLock(); });
          })(btns[bi]);
        }
      }
    }

    // 点击画面恢复指针锁定（菜单开着时先关菜单）
    document.getElementById('game-canvas').addEventListener('mousedown', function () {
      if (ui.pauseOpen && !player.locked) { ui.togglePause(false); }
      if (ui.pickerOpen && !player.locked) { ui.togglePicker(false); }
    });

    // ---------- 5. 预热：出生点周围 3×3 区块（同步，加载条）----------
    var loadingEl = document.getElementById('loading');
    var loadingText = loadingEl ? loadingEl.querySelector('.loading-text') : null;
    if (loadingText) loadingText.textContent = '正在生成世界… (seed=' + seed + ')';
    ui.setLoading(5);

    var scx = Math.floor(spawn.x / CHUNK), scz = Math.floor(spawn.z / CHUNK);
    for (var dx = -1; dx <= 1; dx++) {
      for (var dz = -1; dz <= 1; dz++) world.ensureData(scx + dx, scz + dz);
    }
    ui.setLoading(45);
    // 同步网格化中心区块（预算放大，一次性把 3×3 全部 mesh 完）
    var meshed = 0, guard = 0;
    world.setPlayerPos(spawn.x, spawn.z);
    while (guard++ < 64) {
      var before = meshed;
      world.update(24, function (info) {
        addChunkSafe(info.cx, info.cz, info.geoms);
        meshed++;
      });
      ui.setLoading(45 + Math.min(50, meshed * 6));
      if (meshed === before) break;
    }
    ui.setLoading('done');

    // ---------- 6. 主循环 ----------
    var canvas = document.getElementById('game-canvas');
    var lastT = performance.now();
