    function addChunkSafe(cx, cz, geoms) {
      var key = cx + ',' + cz;
      if (rendered.has(key)) MC_RENDER.removeChunk(cx, cz); // 重网格化前先移除旧网格
      MC_RENDER.addChunk(cx, cz, geoms);
      rendered.set(key, true);
    }

    function unloadFar() {
      var pcx = Math.floor(player.pos.x / CHUNK), pcz = Math.floor(player.pos.z / CHUNK);
      var RD = world.renderDistance;
      var keys = [];
      rendered.forEach(function (v, k) { keys.push(k); });
      for (var i = 0; i < keys.length; i++) {
        var parts = keys[i].split(',');
        var cx = +parts[0], cz = +parts[1];
        var ddx = cx - pcx, ddz = cz - pcz;
        if (ddx * ddx + ddz * ddz > (RD + 2) * (RD + 2)) {
          MC_RENDER.removeChunk(cx, cz);
          rendered.delete(keys[i]);
        }
      }
    }

    function frame(now) {
      requestAnimationFrame(frame);
      var dt = Math.min((now - lastT) / 1000, 0.1);
      lastT = now;
      fps = fps * 0.92 + (dt > 0 ? 1 / dt : 60) * 0.08;

      var paused = ui.pauseOpen || ui.pickerOpen;

      // —— 模拟 ——
      if (!paused) {
        dayTime = (dayTime + dt) % DAY_LEN;
        player.update(dt);
      }
      world.setPlayerPos(player.pos.x, player.pos.z);
      world.update(6, function (info) { addChunkSafe(info.cx, info.cz, info.geoms); });

      // —— 昼夜 ——
      var dayFactor = 0.5 - 0.5 * Math.cos(2 * Math.PI * dayTime / DAY_LEN);
      MC_RENDER.setDayFactor(dayFactor);

      // —— 水下判定与雾 ——
      var eyeBlock = world.getBlock(
        Math.floor(MC_RENDER.camera.position.x),
        Math.floor(MC_RENDER.camera.position.y),
