(function () {
  'use strict';

  // 图集 canvas 上的瓦片源坐标（atlas.js：索引 i → 列 i%16、行 (i/16)|0，像素左上原点）
  function tileSrc(name) {
    var atlas = window.MC_ATLAS;
    if (!atlas || !atlas.T || atlas.T[name] === undefined) return null;
    var i = atlas.T[name];
    return { col: i % 16, row: (i / 16) | 0 };
