        item.appendChild(cv);
        var label = document.createElement('div');
        label.className = 'picker-name';
        label.textContent = def.name;
        item.appendChild(label);
        item.addEventListener('click', function () {
          self.setSlot(self.selected, bid);
          self.togglePicker(false);
          if (self.onPick) self.onPick(bid); // main 用来同步 player.selectedBlock
        });
        grid.appendChild(item);
      })(id);
    }
    this.picker.appendChild(grid);
  };

  // ---------------- 暂停菜单 ----------------
  UI.prototype.togglePause = function (open) {
    if (!this.pause) return;
    this.pauseOpen = (open === undefined) ? !this.pauseOpen : !!open;
    this.pause.style.display = this.pauseOpen ? 'flex' : 'none';
  };
  // 「操作说明」：把键位表写进暂停菜单的说明区（main 初始化时调用一次）
  UI.prototype.setHelpText = function (html) {
    if (!this.pause) return;
    var box = this.pause.querySelector('.help-text');
    if (box) box.innerHTML = html;
  };

  // ---------------- 调试 (F3) ----------------
  UI.prototype.setDebug = function (text) {
    if (!this.debug) return;
    if (text === null || text === undefined) {
      this.debug.style.display = 'none';
    } else {
      this.debug.style.display = 'block';
      // textPre 支持多行
      this.debug.innerHTML = '';
      var lines = String(text).split('\n');
      for (var i = 0; i < lines.length; i++) {
        var div = document.createElement('div');
        div.textContent = lines[i];
        this.debug.appendChild(div);
      }
    }
  };

  // ---------------- 水下滤镜 ----------------
  UI.prototype.setUnderwater = function (b) {
    if (!this.underwater) return;
    this.underwater.style.display = b ? 'block' : 'none';
  };

  // ---------------- Toast 提示 ----------------
  UI.prototype.toast = function (msg) {
    var t = document.getElementById('toast');
    if (!t) {
      t = document.createElement('div');
      t.id = 'toast';
      document.body.appendChild(t);
    }
    t.textContent = msg;
    t.style.display = 'block';
    if (this._toastTimer) clearTimeout(this._toastTimer);
    var self = this;
    this._toastTimer = setTimeout(function () { t.style.display = 'none'; }, 1800);
  };

  window.MC_UI = { UI: UI };
