{"content":"// ============================================================
// 方块注册表（纯数据，Node 可测）
// window.MC_BLOCKS：数组下标即方块 id，0 号位固定为空气(占位 null)。
// 字段约定（与 docs/CONTRACT.md 一致）：
//   name        中文显示名
//   tex         [top, bottom, side] 三个贴图名（对应 atlas.js T 表键名）
//   solid       是否有碰撞（体素 AABB）
//   opaque      是否完全遮挡（用于面剔除与天光/洞穴判定）
//   cross       十字植物（无碰撞、秒破、非实心）
//   translucent 进入半透明渲染队列（水）
//   cutout      进入镂空(α测试)渲染队列（树叶/玻璃）
//   light       自发光等级 0..14（荧石=14）
// ============================================================
(function () {
  'use strict';

  // 快捷构造：三面同贴图的普通方块
  function cube(name, tex, extra) {
    var e = extra || {};
    return {
      name: name,
      tex: Array.isArray(tex) ? tex : [tex, tex, tex],
      solid: e.solid !== undefined ? e.solid : true,
      opaque: e.opaque !== undefined ? e.opaque : true,
      cross: false,
      translucent: e.translucent || false,
      cutout: e.cutout || false,
      light: e.light || 0
    };
  }

  var AIR = {
    name: '空气',
    tex: null,
    solid: false,
    opaque: false,
    cross: false,
    translucent: false,
    cutout: false,
    light: 0
  };

  var LEAVES = cube('橡树树叶', 'leaves', { opaque: false, cutout: true });

  var BLOCKS = [
    /* 0 */ AIR,
    /* 1 */ cube('石头', 'stone'),
    /* 2 */ cube('草方块', ['grass_top', 'dirt', 'grass_side']),
    /* 3 */ cube('泥土', 'dirt'),
    /* 4 */ cube('圆石', 'cobblestone'),
    /* 5 */ cube('橡木木板', 'oak_planks'),
    /* 6 */ cube('基岩', 'bedrock'), // 不可破坏：由 player.js 按 id===6 特判
    /* 7 */ cube('沙子', 'sand'),
    /* 8 */ cube('砂砾', 'gravel'),
    /* 9 */ cube('橡木原木', ['oak_log_top', 'oak_log_top', 'oak_log_side']),
    /*10 */ LEAVES,
    /*11 */ cube('水', 'water', { solid: false, opaque: false, translucent: true }),
    /*12 */ cube('玻璃', 'glass', { opaque: false, cutout: true }),
    /*13 */ cube('煤矿石', 'coal_ore'),
    /*14 */ cube('铁矿石', 'iron_ore'),
    /*15 */ cube('金矿石', 'gold_ore'),
    /*16 */ cube('钻石矿石', 'diamond_ore'),
    /*17 */ cube('雪草方块', ['snow', 'dirt', 'snow_side']),
    /*18 */ cube('沙石', 'sandstone'),
    /*19 */ cube('黏土块', 'clay'),
    /*20 */ cube('砖块', 'bricks'),
    /*21 */ cube('书架', ['oak_planks', 'oak_planks', 'bookshelf']),
    /*22 */ cube('荧石', 'glowstone', { light: 14 }),
    /*23 */ cross('蒲公英', 'dandelion'),
    /*24 */ cross('玫瑰', 'rose'),
    /*25 */ cross('草丛', 'tall_grass'),
    /*26 */ cube('白桦原木', ['birch_log_top', 'birch_log_top', 'birch_log_side'])
  ];

  // 十字植物构造：无碰撞、非遮挡、秒破
  function cross(name, tex) {
    return {
      name: name,
      tex: [tex, tex, tex],
      solid: false,
      opaque: false,
      cross: true,
      translucent: false,
      cutout: true, // 十字植物走镂空队列，避免被面剔除规则误伤
      light: 0
    };
  }

  // ---- 辅助查询（ST-B/其他模块只读使用）----
  var BY_NAME = {};
  for (var i = 1; i < BLOCKS.length; i++) {
    if (BLOCKS[i] && BLOCKS[i].name) BY_NAME[BLOCKS[i].name] = i;
  }

  var MC_BLOCKS_API = {
    BLOCKS: BLOCKS,
    BY_NAME: BY_NAME,
    AIR: 0,
    STONE: 1,
    GRASS: 2,
    DIRT: 3,
    COBBLE: 4,
    PLANKS: 5,
    BEDROCK: 6,
    SAND: 7,
    GRAVEL: 8,
    LOG: 9,
    LEAVES: 10,
    WATER: 11,
    GLASS: 12,
    COAL_ORE: 13,
    IRON_ORE: 14,
    GOLD_ORE: 15,
    DIAMOND_ORE: 16,
    SNOW_GRASS: 17,
    SANDSTONE: 18,
    CLAY: 19,
    BRICKS: 20,
    BOOKSHELF: 21,
    GLOWSTONE: 22,
    DANDELION: 23,
    ROSE: 24,
    TALL_GRASS: 25,
    BIRCH_LOG: 26,
    // id 有效且非空气
    exists: function (id) { return id > 0 && id < BLOCKS.length; },
    // 是否是水（世界生成与判定高频调用）
    isWater: function (id) { return id === 11; },
    // 可被玩家放置的全部方块（热栏/选择器用）：排除空气、水与基岩
    placeable: function () {
      var out = [];
      for (var j = 1; j < BLOCKS.length; j++) {
        var b = BLOCKS[j];
        if (!b || j === 6 || j === 11) continue;
        out.push(j);
      }
      return out;
    }
  };

  // 导出：浏览器全局 + Node 冒烟测试
  if (typeof window !== 'undefined') {
    window.MC_BLOCKS = BLOCKS;
    window.MC_BLOCKS_API = MC_BLOCKS_API;
  }
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { MC_BLOCKS: BLOCKS, MC_BLOCKS_API: MC_BLOCKS_API };
  }
})();
