{"content":"// ============================================================
// 世界生成 + 区块管理（纯逻辑，Node 可测）
// 禁止引用 THREE / DOM；网格化通过 window.MC_MESHER 透传（浏览器端）。
// 坐标系：整数格，x/z 东西南北，y 向上；区块 16×16，世界高 96，海平面 40。
// 区块数据索引：idx = ((x*16)+z)*96+y，x,z∈[0,16)，y∈[0,96)
// 生成规则见 docs/CONTRACT.md：value-noise 地形/群系/洞穴/矿石/树/植被/荧石。
// ============================================================
(function () {
  'use strict';

  var CHUNK = 16, HEIGHT = 96, SEA = 40;

  var AIR = 0, STONE = 1, GRASS = 2, DIRT = 3, BEDROCK = 6,
      SAND = 7, GRAVEL = 8, LOG = 9, LEAVES = 10, WATER = 11,
      COAL = 13, IRON = 14, GOLD = 15, DIAMOND = 16, SNOW_GRASS = 17,
      SANDSTONE = 18, GLOWSTONE = 22, BIRCH_LOG = 26,
      DANDELION = 23, ROSE = 24, TALL_GRASS = 25;

  // 群系 id 与中文名（调试/调试 UI 可用）
  var BIOME_PLAINS = 0, BIOME_FOREST = 1, BIOME_DESERT = 2, BIOME_SNOW = 3, BIOME_MOUNTAIN = 4;
  var BIOME_NAMES = ['平原', '森林', '沙漠', '雪原', '山地'];

  // ---------------------------------------------------------
  // 哈希与噪声（自实现 value noise，无任何外部依赖）
  // ---------------------------------------------------------
  function hash2i(x, z, seed) {
    var h = Math.imul(x, 374761393) ^ Math.imul(z, 668265263) ^ Math.imul(seed, 1442695041);
    h = Math.imul(h ^ (h >>> 13), 1274126177);
    h ^= h >>> 16;
    return (h >>> 0) / 4294967296; // 0..1
  }
  function hash3i(x, y, z, seed) {
    var h = Math.imul(x, 374761393) ^ Math.imul(y, 2246822519) ^
            Math.imul(z, 668265263) ^ Math.imul(seed, 1442695041);
    h = Math.imul(h ^ (h >>> 13), 1274126177);
    h ^= h >>> 16;
    return (h >>> 0) / 4294967296;
  }
  // 2D value noise（双线性 + smoothstep）
  function noise2(x, z, seed) {
    var x0 = Math.floor(x), z0 = Math.floor(z);
    var fx = x - x0, fz = z - z0;
    var u = fx * fx * (3 - 2 * fx), v = fz * fz * (3 - 2 * fz);
    var a = hash2i(x0, z0, seed), b = hash2i(x0 + 1, z0, seed);
    var c = hash2i(x0, z0 + 1, seed), d = hash2i(x0 + 1, z0 + 1, seed);
    return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
  }
  // 分形叠加（多八度）
  function fbm2(x, z, seed, octaves, persistence) {
    var sum = 0, amp = 1, freq = 1, norm = 0;
    for (var i = 0; i < octaves; i++) {
      sum += noise2(x * freq, z * freq, seed + i * 1013) * amp;
      norm += amp; amp *= persistence; freq *= 2;
    }
    return sum / norm;
  }
  // ridged 噪声：山脊感
  function ridged2(x, z, seed) {
    var n = fbm2(x, z, seed, 3, 0.5);
    var r = 1 - Math.abs(n * 2 - 1);
    return r * r;
  }
  // 3D value noise（三线性，洞穴用）
  function noise3(x, y, z, seed) {
    var x0 = Math.floor(x), y0 = Math.floor(y), z0 = Math.floor(z);
    var fx = x - x0, fy = y - y0, fz = z - z0;
    var u = fx * fx * (3 - 2 * fx), v = fy * fy * (3 - 2 * fy), w = fz * fz * (3 - 2 * fz);
    function L(a, b, t) { return a + (b - a) * t; }
    var c000 = hash3i(x0, y0, z0, seed),         c100 = hash3i(x0 + 1, y0, z0, seed);
    var c010 = hash3i(x0, y0 + 1, z0, seed),     c110 = hash3i(x0 + 1, y0 + 1, z0, seed);
    var c001 = hash3i(x0, y0, z0 + 1, seed),     c101 = hash3i(x0 + 1, y0, z0 + 1, seed);
    var c011 = hash3i(x0, y0 + 1, z0 + 1, seed), c111 = hash3i(x0 + 1, y0 + 1, z0 + 1, seed);
    return L(L(L(c000, c100, u), L(c010, c110, u), v),
             L(L(c001, c101, u), L(c011, c111, u), v), w);
  }
  // 确定性 RNG（每区块独立种子）
  function mulberry32(a) {
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function smoothstep(a, b, t) {
    t = Math.min(1, Math.max(0, (t - a) / (b - a)));
    return t * t * (3 - 2 * t);
  }
  var NOW = (typeof performance !== 'undefined' && performance.now)
    ? function () { return performance.now(); }
    : function () { return Date.now(); };

  function chunkKey(cx, cz) { return cx + ',' + cz; }

  // ---------------------------------------------------------
  // World
  // ---------------------------------------------------------
  function World(seed) {
    seed = (seed | 0) || 1337;
    this.seed = seed;
    this.renderDistance = 6;          // 可调（渲染半径，区块）
    this.chunks = new Map();          // key -> chunk
    this.structureQueue = [];         // 跨区块结构延迟写入（树冠等）
    this.playerX = 0.5; this.playerZ = 0.5; // 队列排序基准（main 每帧 setPlayerPos）
    this._offRadius = 0; this._offsets = null;
  }

  // ---------- 地形轮廓 ----------
  // 基础高度 34..64 + 细节；山地区域 ridged 抬升到 ~90
  World.prototype.terrainHeight = function (wx, wz) {
    var s = this.seed;
    var base = fbm2(wx * 0.008, wz * 0.008, s + 11, 4, 0.5);        // 大尺度起伏
    var detail = fbm2(wx * 0.06, wz * 0.06, s + 12, 2, 0.5);        // 小尺度粗糙
    var h = 34 + base * 28 + (detail - 0.5) * 6;                    // ≈34..65
    // 山地掩码 + ridged 抬升
    var mask = smoothstep(0.55, 0.78, fbm2(wx * 0.0028, wz * 0.0028, s + 14, 2, 0.5));
    if (mask > 0) {
      var ridge = ridged2(wx * 0.006, wz * 0.006, s + 13);
      h += mask * (26 + ridge * 42);                                // 最高 ~90+
    }
    return Math.min(92, Math.max(4, h));
  };
  // 群系：温度+湿度两张低频噪声图
  World.prototype.biomeAt = function (wx, wz) {
    var s = this.seed;
    var mMask = fbm2(wx * 0.0028, wz * 0.0028, s + 14, 2, 0.5);
    if (mMask > 0.72) return BIOME_MOUNTAIN;
    var temp = fbm2(wx * 0.0018, wz * 0.0018, s + 21, 2, 0.5);
    var humid = fbm2(wx * 0.0021, wz * 0.0021, s + 22, 2, 0.5);
    if (temp < 0.34) return BIOME_SNOW;
    if (temp > 0.62 && humid < 0.42) return BIOME_DESERT;
    if (humid > 0.52) return BIOME_FOREST;
    return BIOME_PLAINS;
  };
  // 洞穴：双 3D 噪声相交（意面式）。仅陆上柱（h≥SEA）开挖，防洪水。
  World.prototype._isCave = function (wx, y, wz) {
    var s = this.seed;
    var n1 = noise3(wx * 0.021, y * 0.05, wz * 0.021, s + 31) * 2 - 1;
    if (n1 > 0.09 && n1 < -0.09) return false; // 快速排除（不可能分支，便于引擎优化掉）
    if (n1 > 0.09 || n1 < -0.09) return false;
    var n2 = noise3(wx * 0.021, y * 0.05, wz * 0.021, s + 32) * 2 - 1;
    return n2 > -0.09 && n2 < 0.09;
  };

  // ---------- 区块数据 ----------
  World.prototype.getChunk = function (cx, cz) {
    return this.chunks.get(chunkKey(cx, cz)) || null;
  };
  World.prototype.ensureData = function (cx, cz) {
    var k = chunkKey(cx, cz);
    var c = this.chunks.get(k);
    if (c) return c;
    c = { cx: cx, cz: cz, blocks: new Uint8Array(CHUNK * CHUNK * HEIGHT), dirty: true, meshed: false };
    this.chunks.set(k, c);
    this._generate(c);
    this._flushStructuresFor(cx, cz); // 应用邻区块积压的跨区块结构（树冠等）
    return c;
  };
  World.prototype.getBlock = function (x, y, z) {
    if (y < 0 || y >= HEIGHT) return 0;
    var c = this.chunks.get(chunkKey(x >> 4, z >> 4));
    if (!c) return 0; // 未生成区块返回空气
    return c.blocks[(((x & 15) * CHUNK) + (z & 15)) * HEIGHT + y];
  };
  World.prototype.setBlock = function (x, y, z, id) {
    if (y < 0 || y >= HEIGHT) return false;
    var cx = x >> 4, cz = z >> 4;
    var c = this.ensureData(cx, cz);
    c.blocks[(((x & 15) * CHUNK) + (z & 15)) * HEIGHT + y] = id;
    this._markDirty(cx, cz);
    // 跨界邻块标脏（mesher 面剔除/AO 依赖邻块）
    var lx = x & 15, lz = z & 15;
    if (lx === 0) this._markDirty(cx - 1, cz);
    if (lx === 15) this._markDirty(cx + 1, cz);
    if (lz === 0) this._markDirty(cx, cz - 1);
    if (lz === 15) this._markDirty(cx, cz + 1);
    if ((lx === 0 || lx === 15) && (lz === 0 || lz === 15)) {
      this._markDirty(cx + (lx === 0 ? -1 : 1), cz + (lz === 0 ? -1 : 1)); // 对角（AO 用）
    }
    return true;
  };
  // 结构写入：只写已存在区块（树冠/树干跨区块用），不创建区块
  World.prototype.setBlockRaw = function (x, y, z, id) {
    if (y < 0 || y >= HEIGHT) return;
    var c = this.chunks.get(chunkKey(x >> 4, z >> 4));
    if (!c) return;
    c.blocks[(((x & 15) * CHUNK) + (z & 15)) * HEIGHT + y] = id;
    c.dirty = true;
  };
  World.prototype._markDirty = function (cx, cz) {
    var c = this.chunks.get(chunkKey(cx, cz));
    if (c) c.dirty = true;
  };

  // ---------- 单区块生成 ----------
  World.prototype._generate = function (c) {
    var s = this.seed;
    var bx = c.cx * CHUNK, bz = c.cz * CHUNK;
    var blocks = c.blocks;
    var heights = new Int16Array(CHUNK * CHUNK);
    var biomes = new Uint8Array(CHUNK * CHUNK);

    // 第一遍：高度图 + 群系
    for (var x = 0; x < CHUNK; x++) {
      for (var z = 0; z < CHUNK; z++) {
        var wx = bx + x, wz = bz + z;
        var h = Math.floor(this.terrainHeight(wx, wz));
        heights[x * CHUNK + z] = h;
        biomes[x * CHUNK + z] = this.biomeAt(wx, wz);
      }
    }

    // 第二遍：柱填充（基岩/地表/地下/水/洞穴）
    for (x = 0; x < CHUNK; x++) {
      for (z = 0; z < CHUNK; z++) {
        var col = x * CHUNK + z;
        wx = bx + x; wz = bz + z;
        h = heights[col];
        var biome = biomes[col];
        var beach = (h >= SEA - 2 && h <= SEA + 2); // 海滩：地表为沙
        var underwater = h < SEA;

        // 基岩：y=0 满铺，y=1 30%
        blocks[((x * CHUNK) + z) * HEIGHT + 0] = BEDROCK;
        if (hash3i(wx, 1, wz, s + 77) < 0.3) {
          blocks[((x * CHUNK) + z) * HEIGHT + 1] = BEDROCK;
        }

        // 表层方案
        var surface = GRASS, filler = DIRT, fillerDepth = 3, subsurface = STONE;
        if (biome === BIOME_DESERT) {
          surface = SAND; filler = SAND; fillerDepth = 3; subsurface = SANDSTONE;
        } else if (biome === BIOME_SNOW) {
          surface = SNOW_GRASS; filler = DIRT;
        } else if (biome === BIOME_MOUNTAIN) {
          if (h >= 76) { surface = SNOW_GRASS; filler = STONE; }   // 高山雪帽
          else if (h >= 64) { surface = STONE; filler = STONE; }   // 石头露头
        }
        if (beach || underwater) { surface = SAND; filler = SAND; fillerDepth = 3; subsurface = STONE; }
        if (underwater && hash2i(wx, wz, s + 55) < 0.3) surface = GRAVEL; // 水底砾石点缀

        // 填柱
        for (var y = 1; y <= h; y++) {
          var id;
          if (y === h) id = surface;
          else if (y >= h - fillerDepth) id = filler;
          else id = subsurface;
          if (id === STONE && y >= h - fillerDepth) id = STONE;
          blocks[((x * CHUNK) + z) * HEIGHT + y] = id;
        }
        // 沙漠地下过渡回石头
        if (biome === BIOME_DESERT || beach || underwater) {
          for (y = Math.max(2, h - fillerDepth - 3); y <= h - fillerDepth; y++) {
            if (blocks[((x * CHUNK) + z) * HEIGHT + y] === SANDSTONE) {
              // 保持沙石层，更深处由上方循环已是 STONE
            }
          }
        }

        // 水：地表低于海平面时填到 SEA
        if (underwater) {
          for (y = h + 1; y <= SEA; y++) blocks[((x * CHUNK) + z) * HEIGHT + y] = WATER;
        }

        // 洞穴：y∈[6, 地表-4]；水下柱不开挖（防洪水）
        if (!underwater) {
          var caveTop = h - 4;
          for (y = 6; y <= caveTop; y++) {
            if (blocks[((x * CHUNK) + z) * HEIGHT + y] === BEDROCK) continue;
            if (this._isCave(wx, y, wz)) blocks[((x * CHUNK) + z) * HEIGHT + y] = AIR;
          }
        }
      }
    }

    // 第三遍：矿石（小簇 2-6 连块，只替换石头，按深度分布）
    var rng = mulberry32((s ^ Math.imul(c.cx, 341873128) ^ Math.imul(c.cz, 132897987)) | 0);
    this._ores(blocks, rng);

    // 荧石晶簇：洞穴顶部偶发（顶上有实心、自身为空气的格）
    for (var g = 0; g < 4; g++) {
      var gx = (rng() * CHUNK) | 0, gz = (rng() * CHUNK) | 0, gy = 8 + ((rng() * 40) | 0);
      var gi = ((gx * CHUNK) + gz) * HEIGHT;
      if (gy < HEIGHT - 1 && blocks[gi + gy] === AIR && blocks[gi + gy + 1] === STONE && rng() < 0.5) {
        blocks[gi + gy] = GLOWSTONE;
      }
    }

    // 第四遍：树与植被（基于每列地表）
    for (x = 0; x < CHUNK; x++) {
      for (z = 0; z < CHUNK; z++) {
        col = x * CHUNK + z;
        wx = bx + x; wz = bz + z;
        h = heights[col]; biome = biomes[col];
        if (h <= SEA || h + 1 >= HEIGHT - 8) continue;      // 水下/顶部不放
        var top = blocks[((x * CHUNK) + z) * HEIGHT + h];
        var above = blocks[((x * CHUNK) + z) * HEIGHT + h + 1];
        if (top !== GRASS || above !== AIR) continue;        // 只在草地上、上方为空气

        // 树密度：森林 5% / 平原 1% / 雪原 0.8%（云杉形）/ 沙漠山地 0
        var treeChance = biome === BIOME_FOREST ? 0.05 : biome === BIOME_PLAINS ? 0.01 : biome === BIOME_SNOW ? 0.008 : 0;
        var r = hash3i(wx, 91, wz, s + 101);                 // 用坐标哈希决定，跨区块稳定
        if (treeChance > 0 && r < treeChance) {
          var birch = biome === BIOME_FOREST && hash3i(wx, 92, wz, s + 102) < 0.15;
          this._placeTree(wx, h + 1, wz, biome, birch);
          continue; // 树下不放植被
        }
        // 植被：草丛 10%，花 2%（蒲公英/玫瑰各半）
        var rv = hash3i(wx, 93, wz, s + 103);
        if (rv < 0.10) this._placeStructure(wx, h + 1, wz, TALL_GRASS, true);
        else if (rv < 0.11) this._placeStructure(wx, h + 1, wz, DANDELION, true);
        else if (rv < 0.12) this._placeStructure(wx, h + 1, wz, ROSE, true);
      }
    }
  };

  // 矿石 vein：随机游走 2-6 连块，只替换石头
  World.prototype._ores = function (blocks, rng) {
    var specs = [
      { id: COAL,    veins: 14, yMin: 6,  yMax: 60 },
      { id: IRON,    veins: 9,  yMin: 6,  yMax: 40 },
      { id: GOLD,    veins: 4,  yMin: 6,  yMax: 20 },
      { id: DIAMOND, veins: 2,  yMin: 6,  yMax: 14 }
    ];
    for (var si = 0; si < specs.length; si++) {
      var sp = specs[si];
      for (var v = 0; v < sp.veins; v++) {
        var x = (rng() * CHUNK) | 0, z = (rng() * CHUNK) | 0;
        var y = sp.yMin + ((rng() * (sp.yMax - sp.yMin)) | 0);
        var size = 2 + ((rng() * 5) | 0); // 2..6
        for (var i = 0; i < size; i++) {
          if (x >= 0 && x < CHUNK && z >= 0 && z < CHUNK && y > 1 && y < HEIGHT) {
            var idx = ((x * CHUNK) + z) * HEIGHT + y;
            if (blocks[idx] === STONE) blocks[idx] = sp.id;
          }
          // 随机游走一步
          var dir = (rng() * 6) | 0;
          if (dir === 0) x++; else if (dir === 1) x--;
          else if (dir === 2) y++; else if (dir === 3) y--;
          else if (dir === 4) z++; else z--;
        }
      }
    }
  };

  // 树：橡树/白桦（球形叶）与雪原云杉形（叶塔）
  World.prototype._placeTree = function (wx, wy, wz, biome, birch) {
    var logId = birch ? BIRCH_LOG : LOG;
    if (biome === BIOME_SNOW) {
      // 云杉形：干 5-7，叶塔逐层收窄
      var th = 5 + ((hash3i(wx, 94, wz, this.seed + 104) * 3) | 0);
      var topY = wy + th;
      for (var ly = 0; ly < 4; ly++) {
        var r = ly === 0 ? 0 : (ly < 3 ? 1 : 2);
        var yy = topY - ly;
        for (var dx = -r; dx <= r; dx++) for (var dz = -r; dz <= r; dz++) {
          if (dx === 0 && dz === 0 && ly < 4) continue;
          this._placeStructure(wx + dx, yy, wz + dz, LEAVES, true);
        }
      }
      this._placeStructure(wx, topY + 1, wz, LEAVES, true);
      for (var ty = wy; ty < topY; ty++) this._placeStructure(wx, ty, wz, logId, false);
      return;
    }
    // 橡树/白桦：干 4-6 + 球形叶
    var th2 = 4 + ((hash3i(wx, 94, wz, this.seed + 104) * 3) | 0);
    var top2 = wy + th2 - 1;
    for (var dy = -2; dy <= 1; dy++) {
      var rr = dy < 0 ? 2 : 1;
      var y2 = top2 + dy;
      for (var dx2 = -rr; dx2 <= rr; dx2++) for (var dz2 = -rr; dz2 <= rr; dz2++) {
        if (Math.abs(dx2) === rr && Math.abs(dz2) === rr && rr === 2 &&
            hash3i(wx + dx2, y2, wz + dz2, this.seed + 105) < 0.6) continue; // 削角
        if (dx2 === 0 && dz2 === 0 && dy <= 0) continue; // 干的位置
        this._placeStructure(wx + dx2, y2, wz + dz2, LEAVES, true);
      }
    }
    this._placeStructure(wx, top2 + 1, wz, LEAVES, true);
    for (var ty2 = wy; ty2 <= top2; ty2++) this._placeStructure(wx, ty2, wz, logId, false);
  };

  // 结构写入：目标区块已存在→直接写（soft=只写空气）；否则进延迟队列
  World.prototype._placeStructure = function (x, y, z, id, soft) {
    if (y < 0 || y >= HEIGHT) return;
    var cx = x >> 4, cz = z >> 4;
    var c = this.chunks.get(chunkKey(cx, cz));
    if (c) {
      var idx = (((x & 15) * CHUNK) + (z & 15)) * HEIGHT + y;
      if (!soft || c.blocks[idx] === AIR) c.blocks[idx] = id;
      c.dirty = true;
    } else {
      this.structureQueue.push({ x: x, y: y, z: z, id: id, soft: soft });
    }
  };
  // 区块生成后，应用队列中属于该区块的结构
  World.prototype._flushStructuresFor = function (cx, cz) {
    if (!this.structureQueue.length) return;
    var keep = [];
    for (var i = 0; i < this.structureQueue.length; i++) {
      var e = this.structureQueue[i];
      if ((e.x >> 4) === cx && (e.z >> 4) === cz) {
        var c = this.chunks.get(chunkKey(cx, cz));
        var idx = (((e.x & 15) * CHUNK) + (e.z & 15)) * HEIGHT + e.y;
        if (!e.soft || c.blocks[idx] === AIR) c.blocks[idx] = e.id;
        c.dirty = true;
      } else {
        keep.push(e);
      }
    }
    this.structureQueue = keep;
  };

  // ---------- 出生点 ----------
  // 用纯噪声在 (0,0) 附近找草地表面（不依赖区块数据），优先平原/森林
  World.prototype.spawnPoint = function () {
    for (var r = 0; r <= 24; r++) {
      for (var dx = -r; dx <= r; dx++) {
        for (var dz = -r; dz <= r; dz++) {
          if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
          var h = Math.floor(this.terrainHeight(dx, dz));
          if (h <= SEA || h >= 72) continue;
          var b = this.biomeAt(dx, dz);
          if (b === BIOME_DESERT || b === BIOME_MOUNTAIN) continue;
          this.ensureData(dx >> 4, dz >> 4); // 确保出生区块有数据
          return { x: dx + 0.5, y: h + 1, z: dz + 0.5 };
        }
      }
    }
    this.ensureData(0, 0);
    var h0 = Math.max(SEA + 1, Math.floor(this.terrainHeight(0, 0)));
    return { x: 0.5, y: h0 + 1, z: 0.5 };
  };

  // ---------- 流式更新 ----------
  World.prototype.setPlayerPos = function (x, z) {
    this.playerX = x; this.playerZ = z;
  };
  // 以玩家所在区块为中心、按距离排序的环形偏移表（缓存）
  World.prototype._getOffsets = function (radius) {
    if (!this._offsets || this._offRadius < radius) {
      var list = [];
      for (var dx = -radius; dx <= radius; dx++) {
        for (var dz = -radius; dz <= radius; dz++) {
          list.push({ dx: dx, dz: dz, d2: dx * dx + dz * dz });
        }
      }
      list.sort(function (a, b) { return a.d2 - b.d2; });
      this._offsets = list;
      this._offRadius = radius;
    }
    return this._offsets;
  };
  World.prototype._neighborsReady = function (cx, cz) {
    // mesher 跨界取块 + AO 需要八邻数据齐
    for (var dx = -1; dx <= 1; dx++) for (var dz = -1; dz <= 1; dz++) {
      if (!this.chunks.has(chunkKey(cx + dx, cz + dz))) return false;
    }
    return true;
  };
  // update(budgetMs, onChunkReady)：数据环(半径 RD+1) → 网格化(半径 RD，八邻齐才 mesh)
  // geoms 通过 onChunkReady({cx,cz,geoms}) 回调给 main（main 交给 MC_RENDER）。
  World.prototype.update = function (budgetMs, onChunkReady) {
    var t0 = NOW();
    budgetMs = budgetMs || 6;
    var pcx = Math.floor(this.playerX / CHUNK), pcz = Math.floor(this.playerZ / CHUNK);
    var RD = this.renderDistance, GEN_R = RD + 1;
    var offsets = this._getOffsets(GEN_R + 1);
    var mesher = (typeof window !== 'undefined' && window.MC_MESHER) ? window.MC_MESHER : null;

    // 1) 生成数据环（近→远，单区块原子处理）
    for (var i = 0; i < offsets.length; i++) {
      var o = offsets[i];
      if (o.d2 > GEN_R * GEN_R) break;
      if (!this.chunks.has(chunkKey(pcx + o.dx, pcz + o.dz))) {
        this.ensureData(pcx + o.dx, pcz + o.dz);
        if (NOW() - t0 >= budgetMs) return;
      }
    }

    // 2) 网格化（仅当八邻数据齐；dirty 或未 mesh 的区块）
    if (!mesher) return;
    for (i = 0; i < offsets.length; i++) {
      o = offsets[i];
      if (o.d2 > RD * RD) break;
      var cx = pcx + o.dx, cz = pcz + o.dz;
      var c = this.chunks.get(chunkKey(cx, cz));
      if (!c || (!c.dirty && c.meshed)) continue;
      if (!this._neighborsReady(cx, cz)) continue;
      var geoms = mesher.buildChunk(this, cx, cz);
      c.dirty = false; c.meshed = true;
      if (onChunkReady) onChunkReady({ cx: cx, cz: cz, geoms: geoms });
      if (NOW() - t0 >= budgetMs) return;
    }
  };
  // 调试：队列长度
  World.prototype.pendingStats = function () {
    var pcx = Math.floor(this.playerX / CHUNK), pcz = Math.floor(this.playerZ / CHUNK);
    var RD = this.renderDistance, GEN_R = RD + 1;
    var offsets = this._getOffsets(GEN_R + 1);
    var genQ = 0, meshQ = 0;
    for (var i = 0; i < offsets.length; i++) {
      var o = offsets[i];
      if (o.d2 > GEN_R * GEN_R) break;
      if (!this.chunks.has(chunkKey(pcx + o.dx, pcz + o.dz))) genQ++;
    }
    for (i = 0; i < offsets.length; i++) {
      o = offsets[i];
      if (o.d2 > RD * RD) break;
      var cx = pcx + o.dx, cz = pcz + o.dz;
      var c = this.chunks.get(chunkKey(cx, cz));
      if (c && (c.dirty || !c.meshed) && this._neighborsReady(cx, cz)) meshQ++;
    }
    return { genQueue: genQ, meshQueue: meshQ };
  };

  // ---------- 导出（浏览器全局 + Node 冒烟测试）----------
  if (typeof window !== 'undefined') {
    window.MC_WORLD = { World: World, CHUNK: CHUNK, HEIGHT: HEIGHT, SEA: SEA };
  }
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { World: World, CHUNK: 16, HEIGHT: 96, SEA: 40 };
  }
})();
