{"content":"// ============================================================
// 玩家与交互（浏览器端运行；世界逻辑依赖 window.MC_WORLD.World）
// 创造·经典模式：默认飞行、秒破、无生命值。
//   物理：重力 32、跳速 9、走 4.3、疾跑 5.6、飞 11/22、眼高 1.62、
//         碰撞盒 0.6×1.8×0.6，分轴 AABB vs 体素步进碰撞。
//   射线：Amanatides & Woo 体素 DDA，reach=5；水/空气不可选中，十字植物可选中。
//   交互：左键按住连破(0.25s)、右键按住连放(0.25s)、中键取色到热栏。
//   输入：本文件自绑定键鼠；E/ESC/F3/数字键/滚轮通过回调转给 main→ui。
// ============================================================
(function () {
  'use strict';

  var CHUNK = 16, HEIGHT = 96;
  var AIR = 0, STONE = 1, GRASS = 2, DIRT = 3, BEDROCK = 6, WATER = 11;

  // 物理常数（格/秒、格/秒²）
  var GRAVITY = 32, JUMP_V = 9, WALK = 4.3, SPRINT = 5.6, SNEAK = 1.3,
      FLY = 11, FLY_SPRINT = 22, SWIM = 3.2,
      EYE = 1.62, HALF_W = 0.3, HEIGHT_P = 1.8,
      REACH = 5, ACT_INTERVAL = 0.25, TERMINAL_VY = -64;

  function Player(world, camera) {
    this.world = world;
    this.camera = camera;
    this.pos = { x: 0.5, y: 80, z: 0.5 };   // 脚底中心
    this.vel = { x: 0, y: 0, z: 0 };
    this.yaw = 0; this.pitch = 0;           // 弧度
    this.fly = true;                        // 创造默认飞行
    this.sprint = false;
    this.onGround = false;
    this.inWater = false;
    this.spawn = { x: 0.5, y: 80, z: 0.5 };
    this.selectedBlock = 2;                 // 当前放置方块（main/ui 设置）

    // 输入状态
    this.keys = {};
    this.mouseDown = [false, false, false];
    this.locked = false;
    this._lastBreak = -1e9; this._lastPlace = -1e9;
    this._lastSpaceTap = -1e9; this._lastWTap = -1e9;
    this._sens = 0.0022;

    this.canvas = null;
    this.hooks = {};                        // main 注入的语义回调
    this._audio = null;
  }

  // ---------------- 输入绑定 ----------------
  // hooks: { onPauseRequest(), onTogglePicker(), onToggleDebug(), onHotbarSelect(i),
  //          onPickBlock(id), onSlotScroll(dir) }
  Player.prototype.bindInput = function (canvas, hooks) {
    var self = this;
    this.canvas = canvas;
    this.hooks = hooks || {};

    document.addEventListener('keydown', function (e) {
      if (e.repeat) return;
      var k = e.code;
      self.keys[k] = true;

      // —— 需要转交的语义键（无论是否锁定都响应 UI 类按键）——
      if (k === 'KeyE') { self.hooks.onTogglePicker && self.hooks.onTogglePicker(); e.preventDefault(); return; }
      if (k === 'F3') { self.hooks.onToggleDebug && self.hooks.onToggleDebug(); e.preventDefault(); return; }
      if (k === 'Escape') { self.hooks.onPauseRequest && self.hooks.onPauseRequest(); return; }
      if (/^Digit[1-9]$/.test(k)) {
        self.hooks.onHotbarSelect && self.hooks.onHotbarSelect(parseInt(k.slice(5), 10) - 1);
        return;
      }
      if (!self.locked) return; // 仅锁定时响应游戏键

      if (k === 'KeyF') { self.toggleFly(); return; }
      if (k === 'Space') {
        var now = nowSec();
        if (now - self._lastSpaceTap < 0.3) self.toggleFly(); // 双击空格切飞行
        self._lastSpaceTap = now;
        return;
      }
      if (k === 'KeyW') {
        var now2 = nowSec();
        if (now2 - self._lastWTap < 0.3) self.sprint = true;  // 双击 W 疾跑
        self._lastWTap = now2;
      }
    });
    document.addEventListener('keyup', function (e) {
      self.keys[e.code] = false;
      if (e.code === 'KeyW') self.sprint = false; // 松开 W 结束疾跑
    });

    // 点击画面 → 进入指针锁定
    canvas.addEventListener('mousedown', function (e) {
      if (!self.locked) { self.requestLock(); return; }
      self.mouseDown[e.button] = true;
      if (e.button === 2) { self._lastPlace = -1e9; }   // 立即放置
      if (e.button === 0) { self._lastBreak = -1e9; }   // 立即破坏
      if (e.button === 1) {                             // 中键取方块
        var hit = self.raycast();
        if (hit) self.hooks.onPickBlock && self.hooks.onPickBlock(hit.id);
        e.preventDefault();
      }
    });
    document.addEventListener('mouseup', function (e) { self.mouseDown[e.button] = false; });
    document.addEventListener('contextmenu', function (e) { e.preventDefault(); });

    document.addEventListener('mousemove', function (e) {
      if (!self.locked) return;
      self.yaw -= e.movementX * self._sens;
      self.pitch -= e.movementY * self._sens;
      var lim = Math.PI / 2 - 0.001;
      if (self.pitch > lim) self.pitch = lim;
      if (self.pitch < -lim) self.pitch = -lim;
    });

    document.addEventListener('wheel', function (e) {
      if (!self.locked) return;
      self.hooks.onSlotScroll && self.hooks.onSlotScroll(e.deltaY > 0 ? 1 : -1);
      e.preventDefault();
    }, { passive: false });

    // 指针锁定状态跟踪（ESC 由浏览器解除锁定 → main 收到 onPauseRequest 弹菜单）
    document.addEventListener('pointerlockchange', function () {
      self.locked = document.pointerLockElement === canvas;
      if (!self.locked) { self.mouseDown = [false, false, false]; self.keys = {}; }
    });
  };

  Player.prototype.requestLock = function () {
    if (this.canvas && this.canvas.requestPointerLock) {
      try { this.canvas.requestPointerLock(); } catch (e) { /* 忽略 */ }
    }
  };
  Player.prototype.releaseLock = function () {
    if (this.locked && document.exitPointerLock) document.exitPointerLock();
  };

  // ---------------- 帮助函数 ----------------
  function nowSec() {
    return (typeof performance !== 'undefined' && performance.now) ? performance.now() / 1000 : Date.now() / 1000;
  }
  function blockAt(world, x, y, z) {
    var id = world.getBlock(Math.floor(x), Math.floor(y), Math.floor(z));
    var def = (typeof window !== 'undefined' && window.MC_BLOCKS) ? window.MC_BLOCKS[id] : null;
    return { id: id, def: def };
  }
  function isSolidId(id) {
    var def = (typeof window !== 'undefined' && window.MC_BLOCKS) ? window.MC_BLOCKS[id] : null;
    return !!(def && def.solid);
  }
  // 玩脚底是否触地（脚下方块实心）
  Player.prototype._feetOnGround = function () {
    var y = Math.floor(this.pos.y - 0.001);
    var x0 = Math.floor(this.pos.x - HALF_W), x1 = Math.floor(this.pos.x + HALF_W);
    var z0 = Math.floor(this.pos.z - HALF_W), z1 = Math.floor(this.pos.z + HALF_W);
    for (var x = x0; x <= x1; x++) for (var z = z0; z <= z1; z++) {
      if (isSolidId(this.world.getBlock(x, y, z))) return true;
    }
    return false;
  };

  // ---------------- 体素 DDA 射线（Amanatides & Woo）----------------
  // 返回 {x,y,z, nx,ny,nz, id, dist} 或 null；水(11)与空气不可选中。
  Player.prototype.raycast = function () {
    var dir = this._forward();
    var ox = this.pos.x, oy = this.pos.y + EYE, oz = this.pos.z;
    var x = Math.floor(ox), y = Math.floor(oy), z = Math.floor(oz);

    var stepX = dir.x > 0 ? 1 : -1, stepY = dir.y > 0 ? 1 : -1, stepZ = dir.z > 0 ? 1 : -1;
    var tDx = Math.abs(1 / dir.x), tDy = Math.abs(1 / dir.y), tDz = Math.abs(1 / dir.z); // 0 → Infinity
    var tMaxX = (stepX > 0 ? (x + 1 - ox) : (ox - x)) * tDx;
    var tMaxY = (stepY > 0 ? (y + 1 - oy) : (oy - y)) * tDy;
    var tMaxZ = (stepZ > 0 ? (z + 1 - oz) : (oz - z)) * tDz;

    // 起始格自身可选中（例如站在草丛里）— 无面法线
    var id0 = this.world.getBlock(x, y, z);
    if (id0 !== AIR && id0 !== WATER) return { x: x, y: y, z: z, nx: 0, ny: 0, nz: 0, id: id0, dist: 0 };

    var nx = 0, ny = 0, nz = 0, t = 0;
    while (t <= REACH) {
      if (tMaxX < tMaxY && tMaxX < tMaxZ) {
        x += stepX; t = tMaxX; tMaxX += tDx; nx = -stepX; ny = 0; nz = 0;
      } else if (tMaxY < tMaxZ) {
        y += stepY; t = tMaxY; tMaxY += tDy; nx = 0; ny = -stepY; nz = 0;
      } else {
        z += stepZ; t = tMaxZ; tMaxZ += tDz; nx = 0; ny = 0; nz = -stepZ;
      }
      if (t > REACH) break;
      var id = this.world.getBlock(x, y, z);
      if (id !== AIR && id !== WATER) {
        return { x: x, y: y, z: z, nx: nx, ny: ny, nz: nz, id: id, dist: t };
      }
    }
    return null;
  };
  Player.prototype._forward = function () {
    var cy = Math.cos(this.yaw), sy = Math.sin(this.yaw);
    var cp = Math.cos(this.pitch), sp = Math.sin(this.pitch);
    return { x: -sy * cp, y: sp, z: -cy * cp };
  };

  // ---------------- 破坏 / 放置 ----------------
  Player.prototype.tryBreak = function () {
    var hit = this.raycast();
    if (!hit) return;
    if (hit.id === BEDROCK) return;          // 基岩不可破坏
    this.world.setBlock(hit.x, hit.y, hit.z, AIR);
    // 上方是十字植物 → 一并移除（防悬空花草）
    var above = this.world.getBlock(hit.x, hit.y + 1, hit.z);
    var aboveDef = window.MC_BLOCKS && window.MC_BLOCKS[above];
    if (aboveDef && aboveDef.cross) this.world.setBlock(hit.x, hit.y + 1, hit.z, AIR);
    this._sound('break');
  };
  Player.prototype.tryPlace = function () {
    var hit = this.raycast();
    if (!hit) return;
    var id = this.selectedBlock | 0;
    if (!id) return;
    var def = window.MC_BLOCKS && window.MC_BLOCKS[id];
    if (!def) return;

    var tx, ty, tz;
    if (hit.nx === 0 && hit.ny === 0 && hit.nz === 0) return; // 起始格无法推面
    // 目标格内已是十字植物 → 直接替换（MC 行为）
    var targetId = this.world.getBlock(hit.x + hit.nx, hit.y + hit.ny, hit.z + hit.nz);
    var targetDef = window.MC_BLOCKS && window.MC_BLOCKS[targetId];
    if (targetDef && targetDef.cross) {
      tx = hit.x + hit.nx; ty = hit.y + hit.ny; tz = hit.z + hit.nz;
    } else {
      tx = hit.x + hit.nx; ty = hit.y + hit.ny; tz = hit.z + hit.nz;
      if (targetId !== AIR && targetId !== WATER) return; // 目标必须为空/水
    }
    // 十字植物只能放在草/泥土上
    if (def.cross) {
      var below = this.world.getBlock(tx, ty - 1, tz);
      if (below !== GRASS && below !== DIRT) return;
    }
    // 不能放进与玩家碰撞盒相交的位置（仅实心方块）
    if (def.solid) {
      var px0 = this.pos.x - HALF_W, px1 = this.pos.x + HALF_W;
      var py0 = this.pos.y, py1 = this.pos.y + HEIGHT_P;
      var pz0 = this.pos.z - HALF_W, pz1 = this.pos.z + HALF_W;
      if (px1 > tx && px0 < tx + 1 && py1 > ty && py0 < ty + 1 && pz1 > tz && pz0 < tz + 1) return;
    }
    this.world.setBlock(tx, ty, tz, id);
    this._sound('place');
  };

  // ---------------- WebAudio 合成音效（短噪声脉冲）----------------
  Player.prototype._sound = function (kind) {
    try {
      if (!this._audio) {
        var AC = window.AudioContext || window.webkitAudioContext;
        if (!AC) return;
        this._audio = new AC();
      }
      var ctx = this._audio;
      if (ctx.state === 'suspended') ctx.resume();
      var dur = kind === 'break' ? 0.09 : 0.06;
      var buf = ctx.createBuffer(1, Math.ceil(ctx.sampleRate * dur), ctx.sampleRate);
      var d = buf.getChannelData(0);
      for (var i = 0; i < d.length; i++) {
        d[i] = (Math.random() * 2 - 1) * (1 - i / d.length); // 衰减白噪声
      }
      var src = ctx.createBufferSource(); src.buffer = buf;
      var g = ctx.createGain();
      g.gain.value = kind === 'break' ? 0.25 : 0.18;
      var f = ctx.createBiquadFilter();
      f.type = 'lowpass'; f.frequency.value = kind === 'break' ? 900 : 1400;
      src.connect(f); f.connect(g); g.connect(ctx.destination);
      src.start();
    } catch (e) { /* 音频失败不影响游戏 */ }
  };

  // ---------------- 物理 ----------------
  Player.prototype.toggleFly = function () {
    this.fly = !this.fly;
    if (this.fly) this.vel.y = 0;
  };
  Player.prototype.teleport = function (p) {
    this.pos.x = p.x; this.pos.y = p.y; this.pos.z = p.z;
    this.vel.x = this.vel.y = this.vel.z = 0;
  };

  // 分轴 AABB vs 体素碰撞：沿单轴移动后，把玩家推出所有相交体素
  Player.prototype._collideAxis = function (axis, delta) {
    if (!delta) return;
    var p = this.pos;
    p[axis] += delta;
    var x0 = Math.floor(p.x - HALF_W), x1 = Math.floor(p.x + HALF_W);
    var y0 = Math.floor(p.y), y1 = Math.floor(p.y + HEIGHT_P);
    var z0 = Math.floor(p.z - HALF_W), z1 = Math.floor(p.z + HALF_W);
    for (var x = x0; x <= x1; x++) {
      for (var y = y0; y <= y1; y++) {
        for (var z = z0; z <= z1; z++) {
          if (!isSolidId(this.world.getBlock(x, y, z))) continue;
          // 与该体素 AABB 相交 → 推回
          if (!(p.x - HALF_W < x + 1 && p.x + HALF_W > x &&
                p.y < y + 1 && p.y + HEIGHT_P > y &&
                p.z - HALF_W < z + 1 && p.z + HALF_W > z)) continue;
          if (axis === 'x') {
            p.x = delta > 0 ? x - HALF_W - 0.001 : x + 1 + HALF_W + 0.001;
            this.vel.x = 0;
          } else if (axis === 'z') {
            p.z = delta > 0 ? z - HALF_W - 0.001 : z + 1 + HALF_W + 0.001;
            this.vel.z = 0;
          } else {
            if (delta > 0) { p.y = y - HEIGHT_P - 0.001; }
            else { p.y = y + 1; this.onGround = true; }
            this.vel.y = 0;
          }
        }
      }
    }
  };

  Player.prototype.update = function (dt) {
    dt = Math.min(dt, 0.05); // 防大步长穿墙
    var k = this.keys;
    var fwd = (k['KeyW'] ? 1 : 0) - (k['KeyS'] ? 1 : 0);
    var strafe = (k['KeyD'] ? 1 : 0) - (k['KeyA'] ? 1 : 0);
    var cy = Math.cos(this.yaw), sy = Math.sin(this.yaw);
    // 期望水平方向（相对相机朝向）
    var wishX = (-sy) * fwd + cy * strafe;
    var wishZ = (-cy) * fwd + (-sy) * strafe;
    var wl = Math.hypot(wishX, wishZ);
    if (wl > 0) { wishX /= wl; wishZ /= wl; }

    // 水检测（脚部/躯干所在格）
    var feet = blockAt(this.world, this.pos.x, this.pos.y + 0.2, this.pos.z);
    var body = blockAt(this.world, this.pos.x, this.pos.y + 0.9, this.pos.z);
    this.inWater = feet.id === WATER || body.id === WATER;

    if (this.fly) {
      // —— 飞行 ——
      var spd = (this.sprint || k['ControlLeft'] || k['ControlRight']) ? FLY_SPRINT : FLY;
      this.vel.x = wishX * spd;
      this.vel.z = wishZ * spd;
      var up = (k['Space'] ? 1 : 0) - ((k['ShiftLeft'] || k['ShiftRight']) ? 1 : 0);
      this.vel.y = up * spd * 0.85;
    } else if (this.inWater) {
      // —— 水中：浮力 + 减速，按住空格上浮 ——
      var wSpd = SWIM * ((this.sprint || k['ControlLeft']) ? 1.3 : 1);
      this.vel.x = wishX * wSpd;
      this.vel.z = wishZ * wSpd;
      if (k['Space']) this.vel.y = 3.6;          // 上浮
      else this.vel.y += (GRAVITY * 0.18) * -dt * 2; // 缓慢下沉
      if (this.vel.y < -3) this.vel.y = -3;
    } else {
      // —— 地面行走 ——
      var gSpd = k['ShiftLeft'] || k['ShiftRight'] ? SNEAK
               : (this.sprint || k['ControlLeft'] || k['ControlRight']) ? SPRINT : WALK;
      var ground = this.onGround;
      var blend = 1 - Math.exp(-(ground ? 14 : 3.5) * dt);
      this.vel.x += (wishX * gSpd - this.vel.x) * blend;
      this.vel.z += (wishZ * gSpd - this.vel.z) * blend;
      this.vel.y -= GRAVITY * dt;
      if (this.vel.y < TERMINAL_VY) this.vel.y = TERMINAL_VY;
      if (k['Space'] && ground) this.vel.y = JUMP_V; // 跳跃初速 9 → 跳高 ~1.25
    }

    // 分轴移动 + 碰撞
    this.onGround = false;
    this._collideAxis('y', this.vel.y * dt);
    this._collideAxis('x', this.vel.x * dt);
    this._collideAxis('z', this.vel.z * dt);
    if (!this.fly && !this.onGround && this.vel.y === 0) this.onGround = this._feetOnGround();

    // 掉出世界 → 传回出生点
    if (this.pos.y < -10) this.teleport(this.spawn);

    // —— 按住连破 / 连放 ——
    var now = nowSec();
    if (this.locked && this.mouseDown[0] && now - this._lastBreak >= ACT_INTERVAL) {
      this.tryBreak(); this._lastBreak = now;
    }
    if (this.locked && this.mouseDown[2] && now - this._lastPlace >= ACT_INTERVAL) {
      this.tryPlace(); this._lastPlace = now;
    }

    // —— 相机同步（眼高 1.62）——
    if (this.camera) {
      this.camera.position.set(this.pos.x, this.pos.y + EYE, this.pos.z);
      var e = this.camera.rotation;
      if (typeof THREE !== 'undefined' && THREE.Euler) {
        this.camera.quaternion.setFromEuler(new THREE.Euler(this.pitch, this.yaw, 0, 'YXZ'));
      } else {
        e.set(this.pitch, this.yaw, 0, 'YXZ'); // 兜底
      }
    }
  };

  // 调试信息（F3 用）
  Player.prototype.debugInfo = function () {
    var dirNames = ['南 +Z', '西 -X', '北 -Z', '东 +X'];
    var a = ((Math.round(this.yaw / (Math.PI / 2)) % 4) + 4) % 4;
    return {
      pos: this.pos,
      chunk: { cx: Math.floor(this.pos.x / CHUNK), cz: Math.floor(this.pos.z / CHUNK) },
      facing: dirNames[a],
      fly: this.fly, inWater: this.inWater, onGround: this.onGround
    };
  };

  window.MC_PLAYER = { Player: Player };
})();
