// js/render.js — ST-B：渲染器 / 场景 / 天空(日月星云) / 三种共享材质 / 区块网格托管 / 高亮框
// r128 API：WebGLRenderer / PerspectiveCamera / Mesh / LineSegments(EdgesGeometry(BoxGeometry))
//           Points / PointsMaterial / ShaderMaterial / CanvasTexture / Color / Fog
(function () {
  'use strict';

  var CHUNK = 16;
  if (window.MC_WORLD) CHUNK = window.MC_WORLD.CHUNK || 16;

  var R = {
    renderer: null,
    scene: null,
    camera: null,
    materials: null,   // {opaque, cutout, translucent}
    chunks: {},        // key "cx,cz" → {opaque:Mesh|null, cutout:..., translucent:...}
    _highlight: null,
    _sun: null, _moon: null, _stars: null, _clouds: null,
    _dayFactor: 1.0,
    _time: 0,
    _fogColor: new THREE.Color(0x87ceeb),
    _fogNear: 60, _fogFar: 88,
    _underwater: false
  };

  // ---------- 材质（由 shaders.js 构造，这里持有并统一同步 uniform） ----------
  function buildMaterials(atlasTexture) {
    var m = window.MC_SHADERS;
    return {
      opaque: m.makeOpaqueMaterial(atlasTexture),
      cutout: m.makeCutoutMaterial(atlasTexture),
      translucent: m.makeWaterMaterial(atlasTexture)
    };
  }

  // ---------- 天空系统 ----------
  // 太阳/月亮：MC 风格方形面片，绕玩家公转（半径 400，绕 x 轴），始终绑定相机位置
  function makeSun() {
    var g = new THREE.PlaneGeometry(60, 60);
    var m = new THREE.MeshBasicMaterial({ color: 0xffffcc, fog: false, transparent: true, opacity: 1, depthWrite: false });
    var mesh = new THREE.Mesh(g, m);
    mesh.renderOrder = -9;
    return mesh;
  }
  function makeMoon() {
    var g = new THREE.PlaneGeometry(45, 45);
    var m = new THREE.MeshBasicMaterial({ color: 0xd8dce8, fog: false, transparent: true, opacity: 1, depthWrite: false });
    var mesh = new THREE.Mesh(g, m);
    mesh.renderOrder = -9;
    return mesh;
  }
  // 星空：随机方向远处点集，夜晚淡入淡出（PointsMaterial.opacity）
  function makeStars() {
    var n = 400, pos = new Float32Array(n * 3), i;
    for (i = 0; i < n; i++) {
      // 均匀球面采样（半径 600，位于远天）
      var u = Math.random() * 2 - 1;
      var th = Math.random() * Math.PI * 2;
      var r = Math.sqrt(1 - u * u);
      pos[i * 3] = 600 * r * Math.cos(th);
      pos[i * 3 + 1] = Math.abs(600 * u);   // 只取上半球
      pos[i * 3 + 2] = 600 * r * Math.sin(th);
    }
    var g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    var m = new THREE.PointsMaterial({
      color: 0xffffff, size: 2.2, sizeAttenuation: false,
      transparent: true, opacity: 0, depthWrite: false, fog: false
    });
    var p = new THREE.Points(g, m);
    p.renderOrder = -10;
    return p;
  }
  // 块状云层：y=100 大平面 + 32×32 程序化 canvas 云图（大格块状 α），transparent、depthWrite:false
  function makeClouds() {
    var size = 32;
    var cv = document.createElement('canvas');
    cv.width = size; cv.height = size;
    var ctx = cv.getContext('2d');
    var img = ctx.createImageData(size, size);
    var i, x, y;
    // 低频 value-noise 阈值 → 块状云斑（每格 0 或 255，无中间值 → MC 味）
    function noise(px, py) { // 简易双线性 value noise
      var x0 = Math.floor(px), y0 = Math.floor(py);
      function h(a, b) {
        var s = (a * 374761393 + b * 668265263) | 0;
        s = (s ^ (s >> 13)) * 1274126177 | 0;
        return ((s ^ (s >> 16)) >>> 0) / 4294967295;
      }
      var fx = px - x0, fy = py - y0;
      var v00 = h(x0, y0), v10 = h(x0 + 1, y0), v01 = h(x0, y0 + 1), v11 = h(x0 + 1, y0 + 1);
      return v00 + (v10 - v00) * fx + (v01 - v00) * fy + (v11 - v10 - v01 + v00) * fx * fy;
    }
    for (y = 0; y < size; y++) {
      for (x = 0; x < size; x++) {
        // 平铺采样：噪声在 size 尺度上重复取模，保证纹理 wrap 无缝
        var n = noise((x % 16) * 0.5, (y % 16) * 0.5);
        var a = n > 0.58 ? 255 : 0;
        img.data[(y * size + x) * 4] = 255;
        img.data[(y * size + x) * 4 + 1] = 255;
        img.data[(y * size + x) * 4 + 2] = 255;
        img.data[(y * size + x) * 4 + 3] = a;
      }
    }
    ctx.putImageData(img, 0, 0);
    var tex = new THREE.CanvasTexture(cv);
    tex.magFilter = THREE.NearestFilter;
    tex.minFilter = THREE.NearestFilter;
    tex.generateMipmaps = false;
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(8, 8);
    var g = new THREE.PlaneGeometry(1024, 1024);
    g.rotateX(-Math.PI / 2); // 平放
    var m = new THREE.MeshBasicMaterial({
      map: tex, transparent: true, opacity: 0.85,
      depthWrite: false, fog: false, side: THREE.DoubleSide
    });
    var mesh = new THREE.Mesh(g, m);
    mesh.renderOrder = 3; // 排在半透明水(2)之后：从上空看云能正确盖住地形，从下看被地形遮挡
    return mesh;
  }
