  // ---------- init ----------
  function init(atlasTexture) {
    var canvas = document.getElementById('game-canvas');
    R.renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: false });
    R.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    R.renderer.setSize(window.innerWidth, window.innerHeight);

    R.scene = new THREE.Scene();
    R.scene.background = new THREE.Color(0x87ceeb);

    R.camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.1, 1000);
    R.camera.position.set(0, 60, 0);

    R.materials = buildMaterials(atlasTexture);

    // 高亮框：黑色 50% 透明的线框盒（比格大 0.002，中心=格+0.5）
    var box = new THREE.BoxGeometry(1.002, 1.002, 1.002);
    var edges = new THREE.EdgesGeometry(box);
    var lineMat = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.5 });
    R._highlight = new THREE.LineSegments(edges, lineMat);
    R._highlight.visible = false;
    R.scene.add(R._highlight);

    // 天空元素（云与日月星随相机移动）
    R._stars = makeStars(); R.scene.add(R._stars);
    R._sun = makeSun(); R.scene.add(R._sun);
    R._moon = makeMoon(); R.scene.add(R._moon);
    R._clouds = makeClouds(); R.scene.add(R._clouds);

    window.addEventListener('resize', resize);
    return R;
  }

  // ---------- 区块网格托管 ----------
  // geoms = {opaque, cutout, translucent}（BufferGeometry|null，mesher 已算好 boundingSphere）
  function addChunk(cx, cz, geoms) {
    var key = cx + ',' + cz;
    removeChunk(cx, cz); // 覆盖重建：先清旧
    var entry = {};
    function make(geom, mat, order) {
      if (!geom) return null;
      var mesh = new THREE.Mesh(geom, mat);
      mesh.position.set(cx * CHUNK, 0, cz * CHUNK);
      mesh.frustumCulled = true;
      mesh.renderOrder = order;
      R.scene.add(mesh);
      return mesh;
    }
    entry.opaque = make(geoms.opaque, R.materials.opaque, 0);
    entry.cutout = make(geoms.cutout, R.materials.cutout, 1);
    entry.translucent = make(geoms.translucent, R.materials.translucent, 2); // 半透明最后画
    R.chunks[key] = entry;
  }
  function removeChunk(cx, cz) {
    var key = cx + ',' + cz;
    var e = R.chunks[key];
    if (!e) return;
    var k;
    for (k in e) {
      if (e[k]) {
        R.scene.remove(e[k]);
        if (e[k].geometry) e[k].geometry.dispose(); // 释放显存
      }
    }
    delete R.chunks[key];
  }
  function chunkCount() {
    var n = 0, k;
    for (k in R.chunks) { if (Object.prototype.hasOwnProperty.call(R.chunks, k)) n++; }
    return n;
  }

  // ---------- 高亮框 ----------
  function setHighlight(visible, x, y, z) {
    if (!R._highlight) return;
    R._highlight.visible = !!visible;
    if (visible) R._highlight.position.set(x + 0.5, y + 0.5, z + 0.5);
  }

  // ---------- 环境控制 ----------
  function setDayFactor(f) {
    R._dayFactor = Math.max(0, Math.min(1, f));
    var bright = 0.25 + 0.75 * R._dayFactor;
    var mats = [R.materials.opaque, R.materials.cutout, R.materials.translucent];
    var i;
    for (i = 0; i < mats.length; i++) {
      mats[i].uniforms.uDayFactor.value = R._dayFactor;
      mats[i].uniforms.uDayBrightness.value = bright;
    }
  }

  function setFog(colorHex, near, far) {
    // 每帧由 main 调用（昼间天空色 / 水下深蓝色），直接应用
    applyFog(colorHex, near, far);
  }
  function applyFog(colorHex, near, far) {
    R._fogColor.setHex(colorHex);
    R._fogNear = near; R._fogFar = far;
    var mats = [R.materials.opaque, R.materials.cutout, R.materials.translucent];
    var i;
    for (i = 0; i < mats.length; i++) {
      mats[i].uniforms.uFogColor.value.setHex(colorHex);
      mats[i].uniforms.uFogNear.value = near;
      mats[i].uniforms.uFogFar.value = far;
    }
  }
  function setUnderwater(b) {
    if (b === R._underwater) return;
    R._underwater = !!b;
    if (b) {
      applyFog(0x1a4f8a, 0, 20); // 深蓝近距雾（main 传的同款参数）
    } else {
      // 恢复：由 main 的 setFog 每帧刷新即可，这里先给一个合理默认
      applyFog(0x87ceeb, 60, 88);
    }
  }
  function setTime(t) {
    R._time = t;
    var mats = [R.materials.opaque, R.materials.cutout, R.materials.translucent];
    var i;
    for (i = 0; i < mats.length; i++) mats[i].uniforms.uTime.value = t;
  }

  // ---------- 每帧更新：昼夜天色插值 / 日月公转 / 星淡入淡出 / 云平移 ----------
  // 天色三段插值：夜(0x0a0e1c) → 晨昏(0xd78f5a) → 昼(0x87ceeb)
  var NIGHT = new THREE.Color(0x0a0e1c);
  var DUSK = new THREE.Color(0xd78f5a);
  var DAY = new THREE.Color(0x87ceeb);
  var tmpColor = new THREE.Color();
  function skyColor(f) {
    if (f < 0.5) {
      // 夜→晨昏：f 0..0.5
      tmpColor.copy(NIGHT).lerp(DUSK, f / 0.5);
    } else {
      // 晨昏→昼：f 0.5..1
      tmpColor.copy(DUSK).lerp(DAY, (f - 0.5) / 0.5);
    }
    return tmpColor;
  }

  function update(dt) {
    var f = R._dayFactor;
    var cam = R.camera;

    // 场景背景：昼间随 dayFactor 插值；水下跟随深蓝雾色。
    // 注意：雾色 uniform 完全由 setFog 维护（main 每帧传入），这里不覆盖，避免冲掉水下雾。
    if (!R._underwater) {
      R.scene.background.copy(skyColor(f));
    } else {
      R.scene.background.copy(R._fogColor);
    }

    // 太阳：沿 x-y 平面公转，a = f*π - π/2（f=1 正午→头顶 / f=0 深夜→地底 / f=0.5 晨昏→地平线）
    var sunAngle = f * Math.PI - Math.PI / 2;
    var sunR = 400;
    R._sun.position.set(
      cam.position.x + Math.cos(sunAngle) * sunR,
      cam.position.y + Math.sin(sunAngle) * sunR,
      cam.position.z
    );
    R._sun.lookAt(cam.position);
    // 月亮：与太阳相对（相位差 π）
    R._moon.position.set(
      cam.position.x - Math.cos(sunAngle) * sunR,
      cam.position.y - Math.sin(sunAngle) * sunR,
      cam.position.z
    );
    R._moon.lookAt(cam.position);

    // 星空：夜晚(f→0)淡入，白天隐没；整体跟随相机（视差为零的天幕感）
    var starMat = R._stars.material;
    starMat.opacity = Math.max(0, 1 - f * 1.6) * 0.9;
    R._stars.position.set(cam.position.x, cam.position.y - 100, cam.position.z);

    // 云层：跟随相机 xz（用 uv offset 平移模拟漂移，云平面本身始终罩在头顶）
    R._clouds.position.set(cam.position.x, 100, cam.position.z);
    var ct = R._time * 0.004; // 缓慢平移
    R._clouds.material.map.offset.set(ct, ct * 0.6);

    // 日月透明度随天色：夜里太阳几乎不可见、月亮明显
    R._sun.material.opacity = Math.max(0, f * 1.2 - 0.15);
    R._moon.material.opacity = Math.max(0, 1 - f * 1.4);
  }

  function resize() {
    if (!R.renderer || !R.camera) return;
    var w = window.innerWidth, h = window.innerHeight;
    R.camera.aspect = w / h;
    R.camera.updateProjectionMatrix();
    R.renderer.setSize(w, h);
  }

  window.MC_RENDER = {
    init: init,
    camera: null,        // init() 后指向 R.camera
    addChunk: addChunk,
    removeChunk: removeChunk,
    chunkCount: chunkCount,
    setHighlight: setHighlight,
    setDayFactor: setDayFactor,
    setFog: setFog,
    setUnderwater: setUnderwater,
    setTime: setTime,
    update: update,
    resize: resize,
    renderer: null       // init() 后指向 R.renderer
  };

  // init() 时把内部对象暴露到公开命名空间
  var _origInit = init;
  window.MC_RENDER.init = function (tex) {
    var r = _origInit(tex);
    window.MC_RENDER.camera = R.camera;
    window.MC_RENDER.renderer = R.renderer;
    return r;
  };
})();

