{"content":"// ============================================================
// HUD / 热栏 / 方块选择器 / 暂停菜单 / 调试 / 加载屏 / 水下滤镜
// DOM 骨架与样式由 index.html（ST-B）提供，按 id 取用：
//   #game-canvas #crosshair #hotbar #block-picker(#picker-grid)
//   #pause-menu(#pause-continue #pause-help-btn #pause-help)
//   #debug #underwater-overlay #loading(#loading-bar-inner) #title-bar
// 图标绘制：用 MC_ATLAS（ST-C 提供 canvas + T 表）截取瓦片画到小 canvas。
// ============================================================
(function () {
  'use strict';

  // 图集 canvas 上的瓦片源坐标（atlas.js：索引 i → 列 i%16、行 (i/16)|0，像素左上原点）
  function tileSrc(name) {
    var atlas = window.MC_ATLAS;
    if (!atlas || !atlas.T || atlas.T[name] === undefined) return null;
    var i = atlas.T[name];
    return { col: i % 16, row: (i / 16) | 0 };
  }

  function UI() {
    this.hotbar = document.getElementById('hotbar');
    this.picker = document.getElementById('block-picker');
    this.pickerGrid = document.getElementById('picker-grid');
    this.pause = document.getElementById('pause-menu');
    this.debug = document.getElementById('debug');
    this.underwater = document.getElementById('underwater-overlay');
    this.loading = document.getElementById('loading');
    this.crosshair = document.getElementById('crosshair');
    this.titleBar = document.getElementById('title-bar');

    this.slotIds = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    this.selected = 0;
    this.pickerOpen = false;
    this.pauseOpen = false;
    this.onPick = null; // 选择器点选后由 main 同步 player.selectedBlock
    this._toastTimer = null;

    // 暂停菜单按钮（index.html 提供 #pause-continue / #pause-help-btn / #pause-help）
    var self = this;
    var cont = document.getElementById('pause-continue');
    if (cont) cont.addEventListener('click', function () { self.togglePause(false); });
    var helpBtn = document.getElementById('pause-help-btn');
    if (helpBtn) helpBtn.addEventListener('click', function () {
      var help = document.getElementById('pause-help');
      if (help) help.style.display = (help.style.display === 'block') ? 'none' : 'block';
    });
  }

  // ---------------- 加载屏 ----------------
  // pct: 0..100 设置进度条宽度；传 'done' 隐藏加载屏并显示 HUD
  UI.prototype.setLoading = function (pct) {
    if (!this.loading) return;
    if (pct === 'done') {
      this.loading.style.display = 'none';
      if (this.crosshair) this.crosshair.style.display = 'block';
      if (this.hotbar) this.hotbar.style.display = 'flex';
      if (this.titleBar) this.titleBar.style.display = 'block';
      return;
    }
    this.loading.style.display = 'flex';
    var bar = document.getElementById('loading-bar-inner');
    var p = Math.max(0, Math.min(100, pct | 0));
    if (bar) bar.style.width = p + '%';
  };

  // ---------------- 方块图标（热栏/选择器共用）----------------
  // 简化像素风：上半画 top 贴图、下半画 side 贴图（压暗模拟 2.5D）；cross 方块画整格十字。
  UI.prototype._drawBlockIcon = function (canvas, id, size) {
    var ctx = canvas.getContext('2d');
    canvas.width = size; canvas.height = size;
    ctx.imageSmoothingEnabled = false;
    ctx.clearRect(0, 0, size, size);

    var atlas = window.MC_ATLAS;
    var blocks = window.MC_BLOCKS;
    var def = blocks && blocks[id];
    if (!atlas || !def) return;
    var srcCanvas = atlas.canvas || (atlas.texture && atlas.texture.image); // ST-C 提供原始画布
    if (!srcCanvas) return;

    function drawTile(tileName, dx, dy, dw, dh, darken) {
      var s = tileSrc(tileName);
      if (!s) return;
      ctx.save();
      if (darken) ctx.filter = 'brightness(0.66)';
      ctx.drawImage(srcCanvas, s.col * 16, s.row * 16, 16, 16, dx, dy, dw, dh);
      ctx.restore();
    }

    if (def.cross) {
      drawTile(def.tex[2], 0, 0, size, size, false);
      return;
    }
    drawTile(def.tex[0], 0, 0, size, size * 0.55, false);          // 顶面（亮）
    drawTile(def.tex[2], 0, size * 0.55, size, size * 0.45, true); // 侧面（暗）
  };

  // ---------------- 热栏 ----------------
  UI.prototype.setHotbar = function (slotIds) {
    if (!slotIds) return;
    for (var i = 0; i < 9; i++) this.slotIds[i] = slotIds[i] | 0;
    this._renderHotbar();
  };
  UI.prototype.setSlot = function (i, id) {
    if (i < 0 || i > 8) return;
    this.slotIds[i] = id | 0;
    this._renderHotbar();
  };
  UI.prototype.selectSlot = function (i) {
    this.selected = Math.max(0, Math.min(8, i));
    this._renderHotbar();
  };
  UI.prototype._renderHotbar = function () {
    if (!this.hotbar) return;
    var self = this;
    // 仅首次重建格子，之后只更新（滚轮切换不重排）
    if (this.hotbar.children.length !== 9) {
      this.hotbar.innerHTML = '';
      for (var i = 0; i < 9; i++) {
        var cell = document.createElement('div');
        cell.className = 'hotbar-slot';
        cell.dataset.index = i;
        cell.appendChild(document.createElement('canvas'));
        cell.addEventListener('click', (function (idx) {
          return function () { self.selectSlot(idx); };
        })(i));
        this.hotbar.appendChild(cell);
      }
    }
    for (var j = 0; j < 9; j++) {
      var el = this.hotbar.children[j];
      el.className = 'hotbar-slot' + (j === this.selected ? ' selected' : '');
      var cv = el.querySelector('canvas');
      var id = this.slotIds[j];
      if (id) this._drawBlockIcon(cv, id, 48);
      else {
        cv.width = 48; cv.height = 48;
        cv.getContext('2d').clearRect(0, 0, 48, 48);
      }
    }
  };

  // ---------------- 方块选择器 ----------------
  // 使用 index.html 的 #picker-grid 容器；每格 class=picker-item（悬停样式由 CSS 提供）
  UI.prototype.togglePicker = function (open) {
    if (!this.picker) return;
    this.pickerOpen = (open === undefined) ? !this.pickerOpen : !!open;
    if (this.pickerOpen) this._buildPicker();
    this.picker.style.display = this.pickerOpen ? 'block' : 'none';
  };
  UI.prototype._buildPicker = function () {
    if (!this.pickerGrid) return;
    var self = this;
    this.pickerGrid.innerHTML = '';
    var blocks = window.MC_BLOCKS;
    for (var id = 1; id < blocks.length; id++) {
      var def = blocks[id];
      if (!def || id === 6 || id === 11) continue; // 排除基岩/水
      (function (bid) {
        var item = document.createElement('div');
        item.className = 'picker-item';
        item.title = def.name;
        var cv = document.createElement('canvas');
        self._drawBlockIcon(cv, bid, 48);
        item.appendChild(cv);
        item.addEventListener('click', function () {
          self.setSlot(self.selected, bid);
          self.togglePicker(false);
          if (self.onPick) self.onPick(bid);
        });
        self.pickerGrid.appendChild(item);
      })(id);
    }
  };

  // ---------------- 暂停菜单 ----------------
  UI.prototype.togglePause = function (open) {
    if (!this.pause) return;
    this.pauseOpen = (open === undefined) ? !this.pauseOpen : !!open;
    this.pause.style.display = this.pauseOpen ? 'flex' : 'none';
  };
  // 「操作说明」内容（main 初始化时注入到 #pause-help）
  UI.prototype.setHelpText = function (html) {
    var help = document.getElementById('pause-help');
    if (help) help.innerHTML = html;
  };

  // ---------------- 调试 (F3) ----------------
  // #debug 样式为 white-space:pre，直接用 textContent 保多行
  UI.prototype.setDebug = function (text) {
    if (!this.debug) return;
    if (text === null || text === undefined) {
      this.debug.style.display = 'none';
    } else {
      this.debug.style.display = 'block';
      this.debug.textContent = String(text);
    }
  };

  // ---------------- 水下滤镜 ----------------
  UI.prototype.setUnderwater = function (b) {
    if (!this.underwater) return;
    this.underwater.style.display = b ? 'block' : 'none';
  };

  // ---------------- Toast 提示（动态创建 #toast）----------------
  UI.prototype.toast = function (msg) {
    var t = document.getElementById('toast');
    if (!t) {
      t = document.createElement('div');
      t.id = 'toast';
      t.style.cssText = 'position:fixed;left:50%;bottom:84px;transform:translateX(-50%);' +
        'z-index:70;background:rgba(0,0,0,0.6);color:#fff;padding:8px 18px;' +
        'font-size:14px;border:2px solid #262626;display:none;text-shadow:1px 1px 0 #000;';
      document.body.appendChild(t);
    }
    t.textContent = msg;
    t.style.display = 'block';
    if (this._toastTimer) clearTimeout(this._toastTimer);
    var self = this;
    this._toastTimer = setTimeout(function () { t.style.display = 'none'; }, 1800);
  };

  window.MC_UI = { UI: UI };
})();
